    public void changeOffice(String office, String currency, ExtentTest logInfo) throws IOException, ClassNotFoundException {

        try {

            if (globalConstants.testEnv.equals("UAT"))
            {
                changePOS(office, logInfo);
                office = mPassengers.get(getDriverID()).get(0).getPOS();
            }


            closeReminderOpenReports(office, currency, logInfo);
            gl.waitForProfileLoad();
            gl.waitProgress();
            System.out.println("office: " + office);
            System.out.println("currency: " + currency);
            gl.waitTillElementEnable(maeGUIObjects.change_Office);
            gl.clickElement(maeGUIObjects.change_Office);
            gl.waitForProfileLoad();
            System.out.println("Change office clicked");
            gl.clickElement(maeGUIObjects.select_Office);
            System.out.println("select office clicked");
            gl.waitForProfileLoad();
            gl.waitProgress();
            gl.mdSelectByValue(maeGUIObjects.office_Dropdown, office);
            System.out.println("Selected office " + office);
            gl.waitProgress();
            gl.waitForProfileLoad();
            gl.waitTillElementEnable(maeGUIObjects.select_currency);
            gl.clickElement(maeGUIObjects.select_currency);
            System.out.println("clicked currency");
            gl.waitForProfileLoad();
            gl.mdSelectByValue(maeGUIObjects.CURRENCY_OPTION, currency);
            gl.waitForProfileLoad();
            gl.waitProgress();
            System.out.println("selected currency - " + currency);


            logInfo.pass("I select sales office and currency");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            maeGUIObjects.changeOffice_OKButton.click();

            gl.waitForProfileLoad();
            WebDriverWait wait = new WebDriverWait(getDriver(), Duration.ofSeconds(220));
            wait.until(ExpectedConditions.invisibilityOfElementLocated(By.xpath("//div[@ng-repeat='(key, val) in spinnerMessage.pssguiSpinnerMessageUtil.loadingMessage']")));
            waitUntilPageLoad(logInfo);
            mPassengers.get(getDriverID()).get(0).setCurrency(currency);

            if (gl.existElement(maeGUIObjects.report_reminder_text) || gl.existElement(maeGUIObjects.REPORT_WARNING_ICON)) {
                closeReports(office, currency, logInfo);
            }
            logInfo.info(MarkupHelper.createLabel("SalesOffice and Currency Changed Successfully", ExtentColor.GREEN));
            setApplicationDate(logInfo);
            gl.highLightErrorMessages(logInfo, "Unable to retrieve flight");
        }catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

