    public void sales_date_change(int i) {

        String newdate = gl.plusDaysFromToday(-i);
        //maeGUIObjects.SALES_DATE.click();
        gl.inputText(maeGUIObjects.SALES_CHANGE_DATE.get(0), Keys.chord(Keys.CONTROL + "a" + Keys.BACK_SPACE));
        gl.inputText(maeGUIObjects.SALES_CHANGE_DATE.get(0), Keys.chord(Keys.BACK_SPACE));
        gl.inputText(maeGUIObjects.SALES_CHANGE_DATE.get(0), newdate);
        //  gl.clickElement(maeGUIObjects.CLOSE_STATION_BUTTON);
        gl.waitProgress();
        gl.waitForProfileLoad();

    }

