    public void refreshTheGUIPage(ExtentTest logInfo) {

        try {

            do {
                getDriver().navigate().refresh();
                gl.waitProgress();
                gl.waitForProfileLoad();

                maeGUIObjects.btn_Reservations.click();
                gl.waitProgress();
                gl.waitForProfileLoad();

                maeGUIObjects.SEARCH_TEXTAREA.sendKeys(mPassengers.get(getDriverID()).get(0).getPnr());
                gl.waitProgress();
                gl.waitForProfileLoad();
                maeGUIObjects.SEARCH_ICON.click();
                gl.waitProgress();
                gl.waitForProfileLoad();

            } while (!maeGUIObjects.FLOWN_STATUS.get(0).getText().equalsIgnoreCase("FLOWN"));

            logInfo.pass("Refreshing GUI to check the FLOWN status");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


