    public void selectCities(String from, String to, ExtentTest logInfo) {
        try {
            for (Passenger pax : mPassengers.get(getDriverID())) {
                pax.setSegmentOriginCity(0, from);
                pax.setSegmentDestinationCity(0, to);
            }

            do {
                maeGUIObjects.INPUT_ORIGIN_CITY.clear();
                maeGUIObjects.INPUT_ORIGIN_CITY.sendKeys(from);
                gl.waitForProfileLoad();
                maeGUIObjects.INPUT_ORIGIN_CITY.sendKeys(Keys.ENTER);
                gl.waitForProfileLoad();
            } while (maeGUIObjects.INPUT_ORIGIN_CITY_ERROR.size() > 0);


            do {
                maeGUIObjects.INPUT_DESTINATION_CITY.clear();
                maeGUIObjects.INPUT_DESTINATION_CITY.sendKeys(to);
                gl.waitForProfileLoad();
                maeGUIObjects.INPUT_DESTINATION_CITY.sendKeys(Keys.ENTER);
                gl.waitForProfileLoad();
            } while (maeGUIObjects.INPUT_DESTINATION_CITY_ERROR.size() > 0);
        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

