    public void enterChildNumber(ExtentTest logInfo) {

        try {
            int paxCount = 0;
            int otherPaxCount = -1;
            for (Passenger passenger : mPassengers.get(getDriverID())) {
                if (passenger.getPaxType().equalsIgnoreCase("CHD"))
                    paxCount++;
                else
                    otherPaxCount++;

            }

            maeGUIObjects.INPUT_CHILD_NUMBER.sendKeys(Keys.CONTROL + "a" + Keys.BACK_SPACE);
            maeGUIObjects.INPUT_CHILD_NUMBER.sendKeys(String.valueOf(paxCount));

            if (otherPaxCount < 0) {
                maeGUIObjects.INPUT_ADULT_NUMBER.sendKeys(Keys.CONTROL + "a" + Keys.BACK_SPACE);
                maeGUIObjects.INPUT_ADULT_NUMBER.sendKeys("0");

                gl.waitForProfileLoad();
                gl.scrollToWebElement(maeGUIObjects.BUTTON_FLIGHT_SEARCH);
                gl.clickButton(maeGUIObjects.BUTTON_FLIGHT_SEARCH);
                logInfo.info("And I click on search button");
                gl.waitProgress();
            }

            if (gl.existElement(maeGUIObjects.ERROR_MESSAGE_AFTER_SEARCH)) {

                logInfo.fail("Availability search failed.  Check your request and try again.");
                Assert.fail("Availability search failed.  Check your request and try again.");

            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }

    }

