                    gl.clickElement(By.xpath("(//toggle-title[@translate='pssgui.quote.result']//preceding::i[1])[" + (i + 1) + "]"));
                    gl.waitProgress();
                    logInfo.info("Child taxes : " + mChildTaxes.get(getDriverID()));
