    public void deleteSecondSegment(ExtentTest logInfo, String SegmentNumber) {
        try {

            if (SegmentNumber.equalsIgnoreCase("2")) {
                gl.waitForProfileLoad();
                gl.clickElement(maeGUIObjects.SECOND_SEGMENT_DELETE);
                gl.waitForProfileLoad();

            } else if (SegmentNumber.equalsIgnoreCase("1")) {
                gl.waitForProfileLoad();
                gl.clickElement(maeGUIObjects.FIRST_SEGMENT_DELETE);
                gl.waitForProfileLoad();

            } else if (SegmentNumber.equalsIgnoreCase("3")) {
                gl.waitForProfileLoad();
                gl.clickElement(maeGUIObjects.THIRD_SEGMENT_DELETE);
                waitUntilPageLoad(logInfo);

            } else if (SegmentNumber.equalsIgnoreCase("4")) {
                gl.waitForProfileLoad();
                gl.clickElement(maeGUIObjects.FOURTH_SEGMENT_DELETE);
                waitUntilPageLoad(logInfo);

            }

            logInfo.pass("I delete the old segment " + SegmentNumber);
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            gl.clickElement(maeGUIObjects.CONFIRM_BUTTON);
            gl.waitProgress();
            gl.waitForProfileLoad();
        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }

    }


