    public void selectGender(ExtentTest logInfo, String Gender) {
        try {
            //Gender Drop Down
            List<WebElement> elements = getDriver().findElements(By.xpath("//pssgui-menu[@menu-model='activePassenger.Gender']//md-select-value//span"));

            String selectedValue = elements.get(0).getText();

            if (selectedValue.equalsIgnoreCase("Gender")) {
                maeGUIObjects.PASSENGER_GENDER_DROPDOWN.click();
                gl.waitForProfileLoad();

                if (Gender.equalsIgnoreCase("Male"))
                    maeGUIObjects.PASSENGER_GENDER_MALE.click();
                else if (Gender.equalsIgnoreCase("Female"))
                    maeGUIObjects.PASSENGER_GENDER_FEMALE.click();
                else if (Gender.equalsIgnoreCase("Unspecified"))
                    maeGUIObjects.PASSENGER_GENDER_UNSPECIFIED.click();
                else if (Gender.equalsIgnoreCase("Undisclosed"))
                    maeGUIObjects.PASSENGER_GENDER_UNDISCLOSED.click();
            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

    public void enterPassengerDetails(ExtentTest logInfo) throws Exception {

        try {
            ArrayList<Passenger> Adults = new ArrayList<>();
            ArrayList<Passenger> Children = new ArrayList<>();
            ArrayList<Passenger> InfantWithSeat = new ArrayList<>();
            ArrayList<Passenger> InfantWithoutSeat = new ArrayList<>();
            ArrayList<Passenger> FQTV = new ArrayList<>();
            ArrayList<Passenger> SeniorAdult = new ArrayList<>();

            int adtCount = 0, chdCount = 0, insCount = 0, infCount = 0, fqtvCount = 0, seniorAdultCount = 0;


            for (Passenger pax : mPassengers.get(getDriverID())) {
                if (pax.getPaxType().equalsIgnoreCase("ADT"))
                    Adults.add(pax);
                else if (pax.getPaxType().equalsIgnoreCase("CHD"))
                    Children.add(pax);
                else if (pax.getPaxType().equalsIgnoreCase("INS"))
                    InfantWithSeat.add(pax);
                else if (pax.getPaxType().equalsIgnoreCase("FQTV"))
                    FQTV.add(pax);
                else if (pax.getPaxType().equalsIgnoreCase("SENIORADT"))
                    SeniorAdult.add(pax);
                else
                    InfantWithoutSeat.add(pax);
            }

            for (int i = 0; i < maeGUIObjects.PASSENGER_TYPE.size(); i++) {
                maeGUIObjects.PASSENGERS.get(i).click();
                gl.waitForProfileLoad();

                String Gender = "NotAvailable";
                String countryCode = "NotAvailable";
                String areaCode = "NotAvailable";
                String phoneNumber = "NotAvailable";

                if (maeGUIObjects.PASSENGER_TYPE.get(i).getText().contains("ADT")) {

                    if (fqtvCount < FQTV.size()) {
                        logInfo.info(MarkupHelper.createLabel("I enter details (FQTV) PAX ", ExtentColor.PURPLE));

                        gl.clickElement(maeGUIObjects.FF_NUMBER_INPUT);
                        gl.inputText(maeGUIObjects.FF_NUMBER_INPUT, FQTV.get(fqtvCount).getFFNumber());

                        gl.clickElement(maeGUIObjects.VALIDATE_FF_NUMBER_BUTTON);
                        gl.waitForProfileLoad();
                        gl.clickElement(maeGUIObjects.ADD_FF_DETAILS_BUTTON);
                        gl.waitProgress();

                        if (!StringUtils.isBlank(maeGUIObjects.INPUT_PASSENGER_DOB.getAttribute("value")))
                            FQTV.get(fqtvCount).setDOB(maeGUIObjects.INPUT_PASSENGER_DOB.getAttribute("value"));

                        Gender = FQTV.get(fqtvCount).getGender();
                        countryCode = FQTV.get(fqtvCount).getCountryCode();
                        areaCode = FQTV.get(fqtvCount).getAreaCode();
                        phoneNumber = FQTV.get(fqtvCount).getPhoneNumber();

                        fqtvCount++;
                    } else if (seniorAdultCount < SeniorAdult.size()) {
                        logInfo.info(MarkupHelper.createLabel("I enter details (seniorAdult) PAX ", ExtentColor.PURPLE));

                        if (!StringUtils.isBlank(maeGUIObjects.INPUT_PASSENGER_DOB.getAttribute("value")))
                            SeniorAdult.get(seniorAdultCount).setDOB(maeGUIObjects.INPUT_PASSENGER_DOB.getAttribute("value"));

                        Gender = SeniorAdult.get(seniorAdultCount).getGender();
                        countryCode = SeniorAdult.get(seniorAdultCount).getCountryCode();
                        areaCode = SeniorAdult.get(seniorAdultCount).getAreaCode();
                        phoneNumber = SeniorAdult.get(seniorAdultCount).getPhoneNumber();

                        seniorAdultCount++;
                    } else {
                        logInfo.info(MarkupHelper.createLabel("I enter details for (ADT) PAX :" + Adults.get(adtCount).getfName() + "/" + Adults.get(adtCount).getlName(), ExtentColor.PURPLE));
                        gl.waitProgress();
                        maeGUIObjects.INPUT_PASSENGER_SURNAME.sendKeys(Adults.get(adtCount).getfName());
                        maeGUIObjects.INPUT_PASSENGER_FIRST_NAME.sendKeys(Adults.get(adtCount).getlName());

                        maeGUIObjects.INPUT_PASSENGER_DOB.clear();
                        Adults.get(adtCount).setDOB(DateUtil.getRandomDOB("ADT"));
                        maeGUIObjects.INPUT_PASSENGER_DOB.sendKeys(Adults.get(adtCount).getDOB());

                        Gender = Adults.get(adtCount).getGender();
                        countryCode = Adults.get(adtCount).getCountryCode();
                        areaCode = Adults.get(adtCount).getAreaCode();
                        phoneNumber = Adults.get(adtCount).getPhoneNumber();

                        adtCount++;
                    }

                } else if (maeGUIObjects.PASSENGER_TYPE.get(i).getText().contains("CHD")) {
                    logInfo.info(MarkupHelper.createLabel("I enter details for (CHD) PAX :" + Children.get(chdCount).getfName() + "/" + Children.get(chdCount).getlName(), ExtentColor.PURPLE));
                    gl.waitProgress();
                    maeGUIObjects.INPUT_PASSENGER_SURNAME.sendKeys(Children.get(chdCount).getfName());
                    maeGUIObjects.INPUT_PASSENGER_FIRST_NAME.sendKeys(Children.get(chdCount).getlName());

                    maeGUIObjects.INPUT_PASSENGER_DOB.clear();
                    Children.get(chdCount).setDOB(DateUtil.getRandomDOB("CHD"));
                    maeGUIObjects.INPUT_PASSENGER_DOB.sendKeys(Children.get(chdCount).getDOB());

                    Gender = Children.get(chdCount).getGender();
                    countryCode = Children.get(chdCount).getCountryCode();
                    areaCode = Children.get(chdCount).getAreaCode();
                    phoneNumber = Children.get(chdCount).getPhoneNumber();

                    chdCount++;
                } else if (maeGUIObjects.PASSENGER_TYPE.get(i).getText().contains("INS")) {
                    logInfo.info(MarkupHelper.createLabel("I enter details for (INS) PAX :" + InfantWithSeat.get(insCount).getfName() + "/" + InfantWithSeat.get(insCount).getlName(), ExtentColor.PURPLE));
                    gl.waitProgress();
                    maeGUIObjects.INPUT_PASSENGER_SURNAME.sendKeys(InfantWithSeat.get(insCount).getfName());
                    maeGUIObjects.INPUT_PASSENGER_FIRST_NAME.sendKeys(InfantWithSeat.get(insCount).getlName());

                    maeGUIObjects.INPUT_PASSENGER_DOB.clear();
                    InfantWithSeat.get(insCount).setDOB(DateUtil.getRandomDOB("INS"));
                    maeGUIObjects.INPUT_PASSENGER_DOB.sendKeys(InfantWithSeat.get(insCount).getDOB());

                    Gender = InfantWithSeat.get(insCount).getGender();
                    insCount++;
                } else if (maeGUIObjects.PASSENGER_TYPE.get(i).getText().contains("INF")) {
                    logInfo.info(MarkupHelper.createLabel("I enter details for (INF) PAX :" + InfantWithoutSeat.get(infCount).getfName() + "/" + InfantWithoutSeat.get(infCount).getlName(), ExtentColor.PURPLE));
                    gl.waitProgress();
                    maeGUIObjects.INPUT_PASSENGER_SURNAME.sendKeys(InfantWithoutSeat.get(infCount).getfName());
                    maeGUIObjects.INPUT_PASSENGER_FIRST_NAME.sendKeys(InfantWithoutSeat.get(infCount).getlName());

                    maeGUIObjects.INPUT_PASSENGER_DOB.clear();
                    InfantWithoutSeat.get(infCount).setDOB(DateUtil.getRandomDOB("INF"));
                    maeGUIObjects.INPUT_PASSENGER_DOB.sendKeys(InfantWithoutSeat.get(infCount).getDOB());

                    if (gl.existElement(maeGUIObjects.PASSENGER_TRAVELS_WITH1)) {

                        maeGUIObjects.PASSENGER_TRAVELS_WITH1.get(0).click();
                        gl.waitForProfileLoad();

                        maeGUIObjects.PASSENGER_TRAVELS_NAME.get(infCount).click();
                        for (Passenger Adt : Adults) {
                            if (maeGUIObjects.PASSENGER_TRAVELS_NAME.get(infCount).getText().contains(Adt.getfName()) &&
                                    maeGUIObjects.PASSENGER_TRAVELS_NAME.get(infCount).getText().contains(Adt.getlName())) {
                                InfantWithoutSeat.get(infCount).setAccompaniedPaxDetails(Adt);
                                break;
                            }

                        }
                    }

                    Gender = InfantWithoutSeat.get(infCount).getGender();
                    infCount++;
                }


                gl.waitForProfileLoad();

                if (gl.existElement(maeGUIObjects.PASSENGER_EMAIL1) && i == 0 && Adults.size() > 0 && StringUtils.isBlank(maeGUIObjects.PASSENGER_EMAIL.getAttribute("value")))
                    gl.inputText(maeGUIObjects.PASSENGER_EMAIL, Adults.get(0).getEmail()); //Entering mail id for only 1 Pax
                else if (gl.existElement(maeGUIObjects.PASSENGER_EMAIL1) && i == 0 && Children.size() > 0 && StringUtils.isBlank(maeGUIObjects.PASSENGER_EMAIL.getAttribute("value")))
                    gl.inputText(maeGUIObjects.PASSENGER_EMAIL, Children.get(0).getEmail());
                else if (gl.existElement(maeGUIObjects.PASSENGER_EMAIL1) && i == 0 && InfantWithSeat.size() > 0 && StringUtils.isBlank(maeGUIObjects.PASSENGER_EMAIL.getAttribute("value")))
                    gl.inputText(maeGUIObjects.PASSENGER_EMAIL, InfantWithSeat.get(0).getEmail());
                else if (gl.existElement(maeGUIObjects.PASSENGER_EMAIL1) && i == 0 && FQTV.size() > 0 && StringUtils.isBlank(maeGUIObjects.PASSENGER_EMAIL.getAttribute("value")))
                    gl.inputText(maeGUIObjects.PASSENGER_EMAIL, InfantWithSeat.get(0).getEmail());

                selectGender(logInfo, Gender);

                gl.waitForProfileLoad();

                if (!maeGUIObjects.PASSENGER_TYPE.get(i).getText().contains("INF")
                        && !maeGUIObjects.PASSENGER_TYPE.get(i).getText().contains("INS")) {

                    selectPhoneType(logInfo);

                    if (StringUtils.isBlank(maeGUIObjects.PASSENGER_COUNTRY_CODE.get(0).getAttribute("value"))) {
                        do {
                            gl.waitProgress();
                            maeGUIObjects.PASSENGER_COUNTRY_CODE.get(0).click();
                            maeGUIObjects.PASSENGER_COUNTRY_CODE.get(0).clear();

                            maeGUIObjects.PASSENGER_COUNTRY_CODE.get(0).sendKeys(countryCode);
                            gl.waitProgress();
                            gl.waitForProfileLoad();
                            maeGUIObjects.PASSENGER_COUNTRY_CODE.get(0).sendKeys(Keys.ENTER);
                            gl.waitProgress();
                            gl.waitForProfileLoad();
                            countryCode = maeGUIObjects.PASSENGER_COUNTRY_CODE.get(0).getAttribute("value");

                        } while ((maeGUIObjects.PASSENGER_COUNTRY_CODE_ERROR.size() > 0) || (StringUtils.isBlank(countryCode)));

                    }

                    if (StringUtils.isBlank(maeGUIObjects.PASSENGER_AREA_CODE.getAttribute("value")))
                        maeGUIObjects.PASSENGER_AREA_CODE.sendKeys(areaCode);

                    gl.waitForProfileLoad();

                    if (StringUtils.isBlank(maeGUIObjects.PASSENGER_PHONE_NUMBER.getAttribute("value")))
                        maeGUIObjects.PASSENGER_PHONE_NUMBER.sendKeys(phoneNumber);

                }

                logInfo.info(MarkupHelper.createLabel("I enter passenger details for : " + maeGUIObjects.PASSENGER_TYPE.get(i).getText(), ExtentColor.GREEN));
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                if (gl.existElement(maeGUIObjects.BOOK_AND_FILEFARE_BUTTONS) && maeGUIObjects.BOOK_AND_FILEFARE_BUTTON.isEnabled())
                    break;
                else if (maeGUIObjects.BOOK_BUTTONS.size() > 1 && maeGUIObjects.BOOK_BUTTON1.isEnabled())
                    break;
                else if (gl.existElement(maeGUIObjects.ADD_NAME_TO_ORDER_BUTTON) && maeGUIObjects.ADD_NAME_TO_ORDER_BUTTON1.isEnabled())
                    break;

                maeGUIObjects.PASSENGERS.get(i + 1).click();

            } //end of for

            org.junit.Assert.assertTrue(gl.existElement(maeGUIObjects.GREEN_CHECKMARK_DISPLAYED));
            logInfo.pass("Passenger verified and Green checkmark ticked..");

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


