    public void twoModesOfPayment(ExtentTest logInfo) {
        try {
            String amountFromGUI = maeGUIObjects.INPUT_AMOUNT.get(0).getAttribute("value");

            String amount1;
            String amount2;

            if (amountFromGUI.contains(".")) {
                BigDecimal Amount = new BigDecimal(amountFromGUI);
                BigDecimal integralPart = Amount.setScale(0, RoundingMode.DOWN); // Truncate decimal part

                BigDecimal amtToSubtract = integralPart.divide(BigDecimal.valueOf(2), 2, RoundingMode.HALF_UP);

                amount1 = String.valueOf(amtToSubtract);
                amount2 = String.valueOf(Amount.subtract(amtToSubtract).setScale(2, RoundingMode.HALF_UP).stripTrailingZeros());

            } else {
                int Amount = Integer.parseInt(amountFromGUI);
                int amtToSubtract;

                if (Amount % 2 == 0)
                    amtToSubtract = Amount / 2;
                else
                    amtToSubtract = (Amount / 2) + (Amount % 2);

                amount1 = String.valueOf(amtToSubtract);
                amount2 = String.valueOf(Amount - amtToSubtract);
            }


            for (Passenger pax : mPassengers.get(getDriverID()))
                pax.setPaymentAmount(amount1 + "/" + amount2);

            logInfo.info(MarkupHelper.createLabel("The Payment Amount is divided in 2 parts : " + amount1 + "/" + amount2, ExtentColor.PURPLE));
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

    public void threeModesOfPayment(ExtentTest logInfo) {
        try {
            String amountFromGUI = maeGUIObjects.INPUT_AMOUNT.get(0).getAttribute("value");

            String amount1;
            String amount2;
            String amount3;

            if (amountFromGUI.contains(".")) {
                BigDecimal Amount = new BigDecimal(amountFromGUI);
                BigDecimal integralPart = Amount.setScale(0, RoundingMode.DOWN); // Truncate decimal part

                BigDecimal amtToSubtract = integralPart.divide(BigDecimal.valueOf(3), 2, RoundingMode.HALF_UP);

                amount1 = String.valueOf(amtToSubtract);
                amount2 = String.valueOf(amtToSubtract);
                amount3 = String.valueOf(Amount.subtract(amtToSubtract.multiply(BigDecimal.valueOf(2))).setScale(2, RoundingMode.HALF_UP).stripTrailingZeros());

            } else {
                int Amount = Integer.parseInt(amountFromGUI);
                int amtToSubtract;

                if (Amount % 3 == 0)
                    amtToSubtract = Amount / 3;
                else
                    amtToSubtract = (Amount / 3) + (Amount % 3);

                amount1 = String.valueOf(amtToSubtract);
                amount2 = String.valueOf(Amount - amtToSubtract - (Amount / 3));
                amount3 = String.valueOf(Amount / 3);
            }


            for (Passenger pax : mPassengers.get(getDriverID()))
                pax.setPaymentAmount(amount1 + "/" + amount2 + "/" + amount3);

            logInfo.info(MarkupHelper.createLabel("The Payment Amount is divided in 3 parts : " + amount1 + "/" + amount2 + "/" + amount3, ExtentColor.PURPLE));
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

