    public void payByBankTransfer(ExtentTest logInfo) throws IOException {
        try {
            logInfo.info(MarkupHelper.createLabel("I make the payment through Misc", ExtentColor.PURPLE));

            gl.clickWebElement(maeGUIObjects.PAYMENT_TYPE_OF_PAYMENT.get(maeGUIObjects.PAYMENT_TYPE_OF_PAYMENT.size() - 1));
            gl.clickWebElement(maeGUIObjects.PAYMENT_WITH_MISC_OPTION.get(maeGUIObjects.PAYMENT_WITH_MISC_OPTION.size() - 1));
            gl.waitForProfileLoad();

            gl.clickWebElement(maeGUIObjects.PAYMENT_SUB_TYPE.get(maeGUIObjects.PAYMENT_SUB_TYPE.size() - 1));
            gl.waitForProfileLoad();

            gl.clickWebElement(maeGUIObjects.PAYMENT_WITH_BANK_TRANSFER.get(maeGUIObjects.PAYMENT_WITH_BANK_TRANSFER.size() - 1));
            gl.waitForProfileLoad();
            gl.scrollToWebElement(maeGUIObjects.INPUT_REFERENCE_NUMBER);
            gl.waitProgress();
            gl.waitElementToBeClick(maeGUIObjects.INPUT_REFERENCE_NUMBER);

            WebElement inputField = maeGUIObjects.INPUT_REFERENCE_NUMBER;
            if (inputField.isEnabled() && inputField.isDisplayed()) {
                inputField.sendKeys("343434343434343");
            } else {
                System.out.println("Element is not ready for interaction.");
            }
            gl.waitForProfileLoad();
            gl.waitProgress();

            maeGUIObjects.INPUT_BANKTRANSFER_DATE.sendKeys(Keys.chord(Keys.CONTROL + "a" + Keys.BACK_SPACE));

            int days = 1;

            LocalDate tomorrow = LocalDate.now().plusDays(days);
            int day = tomorrow.getDayOfMonth();
            String month = tomorrow.getMonth().name();// e.g., AUGUST
            String month1 = month.substring(0, 1) + month.substring(1).toLowerCase();
            String day1 = tomorrow.getDayOfWeek().name();
            String day2 = day1.substring(0, 1) + day1.substring(1).toLowerCase();
            int year = tomorrow.getYear();

            String xpath_SearchOptionSelection2 = "//button[@class='md-datepicker-button md-icon-button md-button md-ink-ripple']";
            WebElement SEARCH_TYPE2 = driver.get().findElement(By.xpath(xpath_SearchOptionSelection2));
            gl.clickElement(SEARCH_TYPE2);

            String xpath = "//tr//td[@aria-label='" + day2 + " " + month1 + " " + day + " " + year + "']";
            WebElement dateElement = getDriver().findElement(By.xpath(xpath));
            dateElement.click();
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");


            logInfo.pass("I make the payment through MISC - BANK TRANSFER");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            if (gl.existElement(maeGUIObjects.ADD_ANOTHER_PAYMENT_BUTTON1)) {
                gl.clickButton(maeGUIObjects.ADD_ANOTHER_PAYMENT_BUTTON);
            } else {
                maeGUIObjects.PAYMENT_PAY_BUTTON.click();
                gl.waitForElementAfterReload(getDriver(), maeGUIObjects.CLOSE_ICON, PAGE_LOAD_TIMEOUT);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }

    }


