            String value1= maeGUIObjects.PAYMENT_AMOUNT1.getText().split(" ")[0];
            BigDecimal amt1 = new BigDecimal(value1);
            System.out.println(amt1);
            String value2= maeGUIObjects.PAYMENT_AMOUNT2.getText().split(" ")[0];
