    public void setEmail(ExtentTest logInfo) {

        try {

            List<WebElement> NEXTBUTTON = driver.get().findElements(By.xpath("//button[contains(@ng-click, 'foid') and normalize-space(text())='Next']"));
            if (gl.existElement(NEXTBUTTON)) {
                gl.scrollToWebElement(maeGUIObjects.FOID_NEXT_BUTTON);
                gl.clickButton(maeGUIObjects.FOID_NEXT_BUTTON);
                gl.waitProgress();
                gl.waitForProfileLoad();
            }

            String email = maeGUIObjects.INPUT_RECIPIENT_EMAIL.getAttribute("value");

            if (StringUtils.isEmpty(email) || !email.equalsIgnoreCase("testone@testone.com")) {
                email = "testone@testone.com";

                maeGUIObjects.INPUT_RECIPIENT_EMAIL.clear();
                maeGUIObjects.INPUT_RECIPIENT_EMAIL.sendKeys(email);
                gl.waitForProfileLoad();
            }

            maeGUIObjects.EmailRecipient_dropDown.click();
            gl.waitForProfileLoad();
            maeGUIObjects.EmailLanguageSelect.click();
            gl.waitForProfileLoad();
            logInfo.pass("I enter the details in the email recipients page");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            maeGUIObjects.EmailButton.click();
            gl.waitProgress();
            WebDriverWait wait = new WebDriverWait(getDriver(), Duration.ofSeconds(120));
            wait.until(ExpectedConditions.invisibilityOfElementLocated(By.xpath("//div[@ng-repeat='(key, val) in spinnerMessage.pssguiSpinnerMessageUtil.loadingMessage']")));

            gl.highLightErrorMessages(logInfo, "Value cannot be null", "purchase operation failed", "Object reference not set");
            gl.highLightErrorMessages(logInfo, "Order retrieval failed", "System Processing Error");

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

    public void validatePayment(ExtentTest logInfo) throws ClassNotFoundException, IOException {

        Passenger pax = mPassengers.get(getDriverID()).get(0);
        try {

            gl.highLightErrorMessages(logInfo, "Order retrieval failed", "Sysytem Processing Error");
            String expected = "Payment Successful";
            String actual = maeGUIObjects.PAYMENT_SUCCESSFUL.getText();
            Assert.assertEquals(expected, actual);

            logInfo.pass("Validated the message - Payment Successful");
            waitUntilPageLoad(logInfo);
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            maeGUIObjects.PaymentDoneButton.click();
            gl.waitProgress();
            gl.waitForProfileLoad();
            logInfo.pass("Order Number Generated: " + pax.getPnr());
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            DateTimeFormatter formatter = DateTimeFormatter.ofPattern("dd-MMM-yyyy");
            LocalDate targetDate;


            String systemDate = maeGUIObjects.SYSYTEM_DATE.getText().substring(0,11);
                targetDate = LocalDate.parse(systemDate, formatter);
                LocalDate today = LocalDate.now();
                long daysBetween = ChronoUnit.DAYS.between(today, targetDate);

                    pax.setSystemDate(0, (int) daysBetween);

//            for (WebElement cos : maeGUIObjects.ORDER_PAGE_FLIGHT_COS) {
                for(int i=0;i<maeGUIObjects.ORDER_PAGE_FLIGHT_COS.size();i++){
                    WebElement cos = maeGUIObjects.ORDER_PAGE_FLIGHT_COS.get(i);
                for (Passenger passenger : mPassengers.get(getDriverID())) {
                    String COS = cos.getText().trim();
                    passenger.setCOS(cos.getText());
                    passenger.setSegmentCOS(i,COS);
                }
            }
        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


    public String commandObtainShipmentNumbersAvailable(String equipmentNumber) {
        return COMMAND_FLIGHT_6 + GET_SHIPMENT_NUMBERS + equipmentNumber;
    }

    public String commandAssignShipmentNumberToFlight(LocalDate departureDate, String flightNumber,
                                                      String origin, String shipmentCode) {
        String departureDateFormatted = DateUtil.formatDateToSharesDateFormat(departureDate);
        return COMMAND_FLIGHT_6 + ASSIGN_SHIPMENT_NUMBER + departureDateFormatted + "\n" + flightNumber + origin + shipmentCode;
    }

    public String commandCheckShipmentAssigned(String flightNumber, LocalDate departureDate, String origin) {
        String departureDateFormatted = DateUtil.formatDateToSharesDateFormat(departureDate);
        return COMMAND_FLIGHT_6 + ASSIGNMENT + flightNumber + "/" + departureDateFormatted + origin;
    }

    public WebElement findElementXpath(String xpath, WebDriver d) {
        return d.findElement(By.xpath(xpath));
    }

    public void assignShipmentNumberToFlightInGUI(int index, ExtentTest logInfo) {

        sharesCancelFlag = 0;
        Passenger pax = mPassengers.get(getDriverID()).get(0);

        String origin = pax.getSegmentOriginCity(index);
        String flightNumber = pax.getSegmentFlight(index);
        LocalDateTime departureDate = DateUtil.formatToLocalDateTime(gl.plusDaysFromTodayNew(pax.getSegmentDate(index)), "10:10");
        System.out.println("Departure Date in Local Date Time format: " + departureDate);

        try {
            logInfo.info(MarkupHelper.createLabel("Click on tools option", ExtentColor.PURPLE));

            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            gl.clickButton(maeGUIObjects.TOOL_MENU);
            gl.waitForProfileLoad();
            logInfo.pass("Click on tools option");

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }

        try {
            logInfo.info(MarkupHelper.createLabel("Click on shares option", ExtentColor.PURPLE));

            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            gl.clickButton(maeGUIObjects.SHARES_OPTION);
            gl.waitProgress();
            gl.waitForProfileLoad();
            logInfo.pass("Click on shares option");

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }


        String command = commandCheckShipmentAssigned(flightNumber,
                departureDate.toLocalDate(), origin);

        try {
            logInfo.info(MarkupHelper.createLabel("Enter Assigned shipment in text area", ExtentColor.PURPLE));

            maeGUIObjects.COMMAND_TEXTAREA.sendKeys(command);

            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            if (maeGUIObjects.SHARES_SUBMIT_BUTTON.size() > 1) {
                gl.clickButton(maeGUIObjects.SHARES_SUBMIT_BUTTON.get(1));
            } else {
                gl.clickButton(maeGUIObjects.SHARES_SUBMIT_BUTTON.get(0));
            }
            gl.waitProgress();
            gl.waitForProfileLoad();

            logInfo.pass("Enter Assigned shipment in text area and click on Submit");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }


        if (gl.existElement(maeGUIObjects.SHIP_NOT_ASSIGNED_MSG)) {
            String departureDateFormatted = DateUtil.formatDateToSharesDateFormat(departureDate.toLocalDate());

            String flightEquipmentLinePath = SHIPMENT_LINE_MSG.replace(FLIGHT_NBR, flightNumber);
            flightEquipmentLinePath = flightEquipmentLinePath.replace(ORIGIN, origin);
            flightEquipmentLinePath = flightEquipmentLinePath.replace(DEPARTURE_DATE, departureDateFormatted);
            String flightEquipmentInfo = findElementXpath(flightEquipmentLinePath, getDriver()).getText();

            flightEquipmentInfo = flightEquipmentInfo.replaceAll("\\s+", " ").trim();
            String[] elements = flightEquipmentInfo.split(" ");
            String equipmentNumber = elements[1].trim();

            command = commandObtainShipmentNumbersAvailable(equipmentNumber);

            try {
                logInfo.info(MarkupHelper.createLabel("Enter shipment numbers in text area", ExtentColor.PURPLE));

                maeGUIObjects.COMMAND_TEXTAREA.sendKeys(command);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                if (maeGUIObjects.SHARES_SUBMIT_BUTTON.size() > 1) {
                    gl.clickButton(maeGUIObjects.SHARES_SUBMIT_BUTTON.get(1));
                } else {
                    gl.clickButton(maeGUIObjects.SHARES_SUBMIT_BUTTON.get(0));
                }

                gl.waitProgress();
                gl.waitForProfileLoad();

                logInfo.pass("Enter shipment numbers in text area and click Submit");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            } catch (AssertionError | Exception e) {

                ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
                Assert.fail("This step failed.. so stopping...");
            }


            String shipmentNumberInfoPath = EQUIPMENT_NUMBERS_DATA_MSG.replace(EQUIPMENT_DATA, equipmentNumber);
            String shipmentNumbersLineInfo = findElementXpath(shipmentNumberInfoPath, getDriver()).getText();

            shipmentNumbersLineInfo = shipmentNumbersLineInfo.replaceAll("\\s+", " ");
            String[] shipmentsElements = shipmentNumbersLineInfo.split(" ");
            String codeToAssign = shipmentsElements[shipmentsElements.length - 1];

            command = commandAssignShipmentNumberToFlight(departureDate.toLocalDate(),
                    flightNumber, origin, codeToAssign);

            try {
                logInfo.info(MarkupHelper.createLabel("Assign shipment number to flight", ExtentColor.PURPLE));

                maeGUIObjects.COMMAND_TEXTAREA.sendKeys(command);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                if (maeGUIObjects.SHARES_SUBMIT_BUTTON.size() > 1) {
                    gl.clickButton(maeGUIObjects.SHARES_SUBMIT_BUTTON.get(1));
                } else {
                    gl.clickButton(maeGUIObjects.SHARES_SUBMIT_BUTTON.get(0));
                }

                gl.waitProgress();
                gl.waitForProfileLoad();

                logInfo.pass("Assign shipment number to flight and click Submit");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            } catch (AssertionError | Exception e) {

                ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
                Assert.fail("This step failed.. so stopping...");
            }

        }
        clickSharesCancel(logInfo);

    }

