    public void passengerCheckIn(ExtentTest logInfo) throws IOException {

        try {
            int x = 0;
            Passenger pax= mPassengers.get(getDriverID()).get(0);

            if (gl.isElementVisible(maeGUIObjects.PRINTER_ACCEPT_BUTTON)) {
                maeGUIObjects.PRINTER_ACCEPT_BUTTON.click();
                gl.waitForProfileLoad();
                gl.waitForProfileLoad();
                gl.ignoreBoardingPassErrorMessage(logInfo, "BOARDING PASS PRINT FAILED");
            }

            do {
                maeGUIObjects.CHECKIN_BUTTON.click();

                WebDriverWait wait = new WebDriverWait(getDriver(), Duration.ofSeconds(120));
                wait.until(ExpectedConditions.invisibilityOfElementLocated(By.xpath("//div[@ng-repeat='(key, val) in spinnerMessage.pssguiSpinnerMessageUtil.loadingMessage']")));
                gl.waitProgress();
                gl.highLightErrorMessages(logInfo, "Checkin operation failed");
                if (x++ >= 5)
                    break;

                if (gl.existElement(maeGUIObjects.FLIGHT_NO_OPEN_ERROR_MSG)) {
                    assignShipmentNumberToFlightInGUI(0, logInfo);
                }

                if (gl.existElement(maeGUIObjects.BAGGAGE_PROCEED_TO_PAY1)) {

                    gl.clickElement(maeGUIObjects.BAGGAGE_PROCEED_TO_PAY);
                    gl.waitProgress();
                    gl.waitForProfileLoad();
                    logInfo.pass("I click on proceed to pay button to do the payment");

                    String paymentType = pax.getPaymentType(0);
                    String amount = maeGUIObjects.INPUT_AMOUNT.get(0).getAttribute("value");
                    pax.setPaymentAmount(amount);
                    makeFirstPayment(paymentType, logInfo);
                    gl.waitProgress();
                    gl.waitForProfileLoad();
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                    clickOnDoneButton(logInfo);
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    logInfo.info("I click done button");
                    clickOnContinueButton(logInfo);
                    logInfo.pass("I click continue button");
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                }

            } while (!gl.isEnabledNew(maeGUIObjects.RETURN_TO_CHECKIN_BUTTON) && !maeGUIObjects.RETURN_TO_CHECKIN_BUTTON.isDisplayed());

            gl.waitForProfileLoad();

            if (gl.isElementVisible(maeGUIObjects.PRINTER_ACCEPT_BUTTON)) {
                maeGUIObjects.PRINTER_ACCEPT_BUTTON.click();
                gl.waitForProfileLoad();
                gl.waitForProfileLoad();
            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }

    }


    public void selectCitiesForFourthSegment(String from, String to, ExtentTest logInfo) {

        try {
            for (Passenger pax : mPassengers.get(getDriverID())) {
                pax.setSegmentOriginCity(3, from);
                pax.setSegmentDestinationCity(3, to);
            }

            maeGUIObjects.ADD_SEGMENT.click();
            do {

                maeGUIObjects.INPUT_ORIGIN_CITY_4.clear();
                maeGUIObjects.INPUT_ORIGIN_CITY_4.sendKeys(from);
                gl.waitForProfileLoad();
                maeGUIObjects.INPUT_ORIGIN_CITY_4.sendKeys(Keys.ENTER);
                gl.waitForProfileLoad();
            } while (maeGUIObjects.INPUT_ORIGIN_CITY_2_ERROR.size() > 0);

            do {
                maeGUIObjects.INPUT_DESTINATION_CITY_4.clear();
                maeGUIObjects.INPUT_DESTINATION_CITY_4.sendKeys(to);
                gl.waitForProfileLoad();
                maeGUIObjects.INPUT_DESTINATION_CITY_4.sendKeys(Keys.ENTER);
                gl.waitForProfileLoad();
            } while (maeGUIObjects.INPUT_DESTINATION_CITY_2_ERROR.size() > 0);

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }

    }


