    public void clickBookButton(ExtentTest logInfo) {
        try {
            gl.waitForProfileLoad();
            maeGUIObjects.BOOK_BUTTON1.click();
            gl.waitProgress();
            gl.waitForProfileLoad();
            gl.waitForElementAfterReload(getDriver(), maeGUIObjects.ORDER_TAB, PAGE_LOAD_TIMEOUT);

            DateTimeFormatter formatter = DateTimeFormatter.ofPattern("dd-MMM-yyyy");
            LocalDate targetDate;

            int x = 0;
            for (WebElement flight : maeGUIObjects.QUOTE_OPTIONS_FLIGHT_NUMBERS) {
                for (Passenger passenger : mPassengers.get(getDriverID())) {
                    passenger.setSegmentFlight(x, flight.getText().substring(2));
                }
                x++;
            }

            x = 0;
            for (WebElement airline : maeGUIObjects.QUOTE_OPTIONS_FLIGHT_NUMBERS) {
                for (Passenger passenger : mPassengers.get(getDriverID())) {
                    passenger.setAirline(x, airline.getText().substring(0, 2));
                }
                x++;
            }

            x = 0;
            for (WebElement segmentDate : maeGUIObjects.QUOTE_OPTIONS_SEGMENT_DEPT_DATES) {
                targetDate = LocalDate.parse(segmentDate.getText(), formatter);
                LocalDate today = LocalDate.now();
                long daysBetween = ChronoUnit.DAYS.between(today, targetDate);

                for (Passenger passenger : mPassengers.get(getDriverID())) {
                    passenger.setSegmentDate(x, (int) daysBetween);
                }
                x++;
            }

            String orderNumber = maeGUIObjects.ORDER_NUMBER.getText();

            for (Passenger pax : mPassengers.get(getDriverID()))
                pax.setPnr(orderNumber);

            for (WebElement cos : maeGUIObjects.BOOK_OPTIONS_FLIGHT_COS) {
                for (Passenger passenger : mPassengers.get(getDriverID())) {
                    passenger.setCOS(cos.getText());
                }
            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

