    public void searchOrderScreenToCheckRemainingSegementsAfterCancel(ExtentTest logInfo, String remainingSegments) {

        Passenger pax = mPassengers.get(getDriverID()).get(0);
        int remainingSegment = Integer.parseInt(remainingSegments);
        String pnr = pax.getPnr();
        try {
            gl.waitForProfileLoad();
            gl.waitProgress();
            maeGUIObjects.btn_Reservations.click();
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            gl.waitProgress();

            for (int i = 0; i <= 50; i++) {
                gl.waitForProfileLoad();
                gl.clickElement(maeGUIObjects.SEARCH_TEXTAREA);
                maeGUIObjects.SEARCH_TEXTAREA.sendKeys(pnr);
                gl.waitForProfileLoad();
                gl.clickButton(maeGUIObjects.SEARCH_ICON);
                gl.waitProgress();
                gl.waitForProfileLoad();
                gl.waitForElementAfterReload(getDriver(), maeGUIObjects.ORDER_TAB, PAGE_LOAD_TIMEOUT);
                List<WebElement> uiSegments = maeGUIObjects.NO_OF_SEGMENTS;
                int uiSegmentSize = uiSegments.size();
                if (uiSegmentSize == remainingSegment) {
                    gl.waitProgress();
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    break;
                } else if (i == 50) {
                    logInfo.fail("The segments has not beeen updated after cancelling");
                    Assert.fail("The segments has not beeen updated after cancelling");
                }

            }
        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");

        }
    }

