    public void searchForPNRAndVerifyCancelledSegment(ExtentTest logInfo, String cancelledSegments) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            gl.clickElement(maeGUIObjects.SEARCH_MENU);
            gl.waitForProfileLoad();
            maeGUIObjects.ITINERARY_INPUT_TEXT.sendKeys(pax.getPnr());
            gl.clickButton(maeGUIObjects.SEARCH_ORDER_BUTTON);

            gl.waitForElementAfterReload(getDriver(), maeGUIObjects.ORDER_TAB, PAGE_LOAD_TIMEOUT);

            int totalSegmentsBeforeDeletion = maeGUIObjects.FLIGHT_ITENARY_DETAILS.size() + Integer.parseInt(cancelledSegments);
            int i = 0;

            do {
                if (i++ > 3)
                    break;
                Thread.sleep(250000);
                maeGUIObjects.HOME_ICON.click();
                gl.clickElement(maeGUIObjects.SEARCH_MENU);
                gl.waitForProfileLoad();
                maeGUIObjects.ITINERARY_INPUT_TEXT.sendKeys(pax.getPnr());
                gl.clickButton(maeGUIObjects.SEARCH_ORDER_BUTTON);
                gl.waitProgress();
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            } while (maeGUIObjects.FLIGHT_ITENARY_DETAILS.size() == totalSegmentsBeforeDeletion);

            int totalSegmentsAfterDeletion = maeGUIObjects.FLIGHT_ITENARY_DETAILS.size();
            Assert.assertEquals(pax.getTotalSegments(), totalSegmentsAfterDeletion);

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }

    }


