    public String getDate(String days) {
        if (days.length() < 2)
            days = "0" + days;

        return days + " Days";
    }

    public void rebookSegmentsOnNewDate(ExtentTest logInfo) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);

            gl.clickElement(maeGUIObjects.ORDER_TAB_AVAILABILITY_EXPAND_BUTTON);
            gl.waitProgress();
            gl.waitForProfileLoad();

            int segmentCount = pax.getTotalSegments();

            logInfo.info(MarkupHelper.createLabel("I Select Origin and Destination for Segments And Add New Date For Reissue", ExtentColor.PURPLE));
            if (segmentCount == 1) {
                selectCitiesFirstSegmentReissue(pax.getSegmentOriginCity(0), pax.getSegmentDestinationCity(0), logInfo);
                bookOneWay(getDate(String.valueOf(pax.getSegmentDate(0) + 20)), logInfo);
            } else if (segmentCount == 2) {
                selectCitiesFirstSegmentReissue(pax.getSegmentOriginCity(0), pax.getSegmentDestinationCity(0), logInfo);
                selectCitiesSecondSegmentReissue(pax.getSegmentOriginCity(1), pax.getSegmentDestinationCity(1), logInfo);

                bookOneWay(getDate(String.valueOf(pax.getSegmentDate(0) + 20)), logInfo);
                book2ndSegment(getDate(String.valueOf(pax.getSegmentDate(1) + 20)), logInfo);
            } else if (segmentCount == 3) {
                selectCitiesFirstSegmentReissue(pax.getSegmentOriginCity(0), pax.getSegmentDestinationCity(0), logInfo);
                selectCitiesSecondSegmentReissue(pax.getSegmentOriginCity(1), pax.getSegmentDestinationCity(1), logInfo);
                selectCitiesThirdSegmentReissue(pax.getSegmentOriginCity(2), pax.getSegmentDestinationCity(2), logInfo);

                bookOneWay(getDate(String.valueOf(pax.getSegmentDate(0) + 20)), logInfo);
                book2ndSegment(getDate(String.valueOf(pax.getSegmentDate(1) + 20)), logInfo);
                book3rdSegment(getDate(String.valueOf(pax.getSegmentDate(2) + 20)), logInfo);
            } else if (segmentCount == 4) {
                selectCitiesFirstSegmentReissue(pax.getSegmentOriginCity(0), pax.getSegmentDestinationCity(0), logInfo);
                selectCitiesSecondSegmentReissue(pax.getSegmentOriginCity(1), pax.getSegmentDestinationCity(1), logInfo);
                selectCitiesThirdSegmentReissue(pax.getSegmentOriginCity(2), pax.getSegmentDestinationCity(2), logInfo);
                selectCitiesFourthSegmentReissue(pax.getSegmentOriginCity(3), pax.getSegmentDestinationCity(3), logInfo);

                bookOneWay(getDate(String.valueOf(pax.getSegmentDate(0) + 20)), logInfo);
                book2ndSegment(getDate(String.valueOf(pax.getSegmentDate(1) + 20)), logInfo);
                book3rdSegment(getDate(String.valueOf(pax.getSegmentDate(2) + 20)), logInfo);
                book4thSegment(getDate(String.valueOf(pax.getSegmentDate(3) + 20)), logInfo);
            } else if (segmentCount == 5) {
                selectCitiesFirstSegmentReissue(pax.getSegmentOriginCity(0), pax.getSegmentDestinationCity(0), logInfo);
                selectCitiesSecondSegmentReissue(pax.getSegmentOriginCity(1), pax.getSegmentDestinationCity(1), logInfo);
                selectCitiesThirdSegmentReissue(pax.getSegmentOriginCity(2), pax.getSegmentDestinationCity(2), logInfo);
                selectCitiesFourthSegmentReissue(pax.getSegmentOriginCity(3), pax.getSegmentDestinationCity(3), logInfo);
                selectCitiesFifthSegmentReissue(pax.getSegmentOriginCity(4), pax.getSegmentDestinationCity(4), logInfo);

                bookOneWay(getDate(String.valueOf(pax.getSegmentDate(0) + 20)), logInfo);
                book2ndSegment(getDate(String.valueOf(pax.getSegmentDate(1) + 20)), logInfo);
                book3rdSegment(getDate(String.valueOf(pax.getSegmentDate(2) + 20)), logInfo);
                book4thSegment(getDate(String.valueOf(pax.getSegmentDate(3) + 20)), logInfo);
                book5thSegment(getDate(String.valueOf(pax.getSegmentDate(4) + 20)), logInfo);
            }

            logInfo.pass("I Successfully select Origin and Destination For Segments and Add new Date");


            logInfo.info(MarkupHelper.createLabel("I Search for Flight Availability", ExtentColor.PURPLE));
            gl.clickButton(maeGUIObjects.BUTTON_FLIGHT_SEARCH);
            gl.waitProgress();
            gl.waitForProfileLoad();
            logInfo.pass("Flight Availability is Shown");

            String COS = pax.getCOS();

            boolean Economy = COS.contains("Y") || COS.contains("B") || COS.contains("H") || COS.contains("M") ||
                    COS.contains("W") || COS.contains("K") || COS.contains("Q") ||
                    COS.contains("E") || COS.contains("F");
            boolean Business = COS.contains("C") || COS.contains("J") || COS.contains("D") || COS.contains("R");

            logInfo.info(MarkupHelper.createLabel("I Select Flights For Segments", ExtentColor.PURPLE));
            if (segmentCount < 2) {
                if (Economy)
                    selectFullEconomy(logInfo);
                else if (Business)
                    selectFullBusiness(logInfo);
            } else {
                if (Economy)
                    selectFullEconomy(logInfo);
                else if (Business)
                    selectFullBusiness(logInfo);

                if (Economy)
                    selectAllFlights("Economy", logInfo);
                else if (Business)
                    selectAllFlights("Business", logInfo);
            }

            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            logInfo.pass("I select the New flights for Segments.");

            logInfo.info(MarkupHelper.createLabel("I Click on Actions Dropdown and select Book Option", ExtentColor.PURPLE));
            gl.clickElement(maeGUIObjects.ACTIONS_DROPDOWN);
            gl.waitForProfileLoad();
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            gl.clickElement(maeGUIObjects.BOOK);
            gl.waitForProfileLoad();
            logInfo.pass("I Clicked on Book Option");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            logInfo.info(MarkupHelper.createLabel("I Select ALl the Newly Booked Segments and Click Book", ExtentColor.PURPLE));

            getDriver().findElement(By.xpath("//md-checkbox[@ng-model='flightResult.isAllChecked']")).click();
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            getDriver().findElement(By.xpath("//button[@translate='pssgui.book']")).click();
            gl.waitProgress();
            gl.waitForProfileLoad();
            logInfo.pass("I Clicked on Book Button");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");


        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            org.junit.Assert.fail("This step failed.. so stopping...");
        }
    }

