    public void clickFlightActions(ExtentTest logInfo) {
        try {
            Passenger pax= mPassengers.get(getDriverID()).get(0);

            if(gl.existElement(maeGUIObjects.FLIGHT_NUMBER_GATE_PAGE1)) {
                String Origin = maeGUIObjects.ORIGIN_CITY_GATE_PAGE.getText().trim();
                String Flight = maeGUIObjects.FLIGHT_NUMBER_GATE_PAGE.getText().trim().substring(2);
                String date = maeGUIObjects.DEPARTURE_DATE_GATE_PAGE.getText();

                DateTimeFormatter formatter = DateTimeFormatter.ofPattern("dd-MMM-yyyy");
                LocalDate targetDate;

                targetDate = LocalDate.parse(date, formatter);
                LocalDate today = LocalDate.now();
                long daysBetween = ChronoUnit.DAYS.between(today, targetDate);

                pax.setSegmentDate(0, (int) daysBetween);
                pax.setSegmentOriginCity(0, Origin);
                pax.setSegmentFlight(0, Flight);
            }

            if (gl.existElement(maeGUIObjects.FLIGHT_NO_OPEN_ERROR_MSG)) {

                assignShipmentNumberToFlightInGUI(0, logInfo);
                gl.waitProgress();

            }

            List<WebElement> Expand_Button = driver.get().findElements(By.xpath("//md-select[@aria-label='Flight Actions']"));

            if (!gl.existElement(Expand_Button)) {
                WebElement Expand_Button1 = driver.get().findElement(By.xpath("//i[@class='icon-expand-flight-info']"));
                gl.waitProgress();
                gl.clickElement(Expand_Button1);
            }
            logInfo.info(MarkupHelper.createLabel("I click on flight actions drop down", ExtentColor.PURPLE));
            maeGUIObjects.DROPDOWN_FLIGHTACTIONS.click();
            gl.waitProgress();
            gl.waitForProfileLoad();
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


    public void selectActionType(ExtentTest logInfo, String actionType) {
        try {
            logInfo.info(MarkupHelper.createLabel("I click on flight action as: " + actionType, ExtentColor.PURPLE));
            String xpath_FlightActions = String.format("//div[@class = 'md-text ng-binding' and contains(text(), '%s')]", actionType);
            WebElement FLIGHT_ACTION = driver.get().findElement(By.xpath(xpath_FlightActions));
            gl.scrollToWebElement(FLIGHT_ACTION);
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            gl.clickElement(FLIGHT_ACTION);
            gl.waitProgress();
            gl.waitForProfileLoad();

            if(gl.existElement(maeGUIObjects.SHIP_NOT_ASSIGNED_ERROR_MSG_GATE_PAGE)){

                assignShipmentNumberToFlightInGUI(0, logInfo);
                gl.waitProgress();
                clickFlightActions(logInfo);
                gl.waitProgress();
                selectActionType(logInfo, actionType);

            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

    public void searchFlightInGate(ExtentTest logInfo, String segmentIndex) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String origin = pax.getSegmentOriginCity(Integer.parseInt(segmentIndex));
            String flightNumber = pax.getSegmentFlight(Integer.parseInt(segmentIndex));
            String dt = String.valueOf(pax.getSegmentDate(Integer.parseInt(segmentIndex)));
            int days = Integer.parseInt(dt);
            String departureDate = gl.plusDaysFromToday(days);

            logInfo.info(MarkupHelper.createLabel("I enter the flight number", ExtentColor.PURPLE));
            gl.clickElement(maeGUIObjects.FLIGHT_NUMBER_IN_GATE);
            gl.inputText(maeGUIObjects.FLIGHT_NUMBER_IN_GATE, flightNumber);

            logInfo.info(MarkupHelper.createLabel("I enter the departure date", ExtentColor.PURPLE));
            gl.clickElement(maeGUIObjects.DEPARTURE_DATE_IN_GATE);
            maeGUIObjects.DEPARTURE_DATE_IN_GATE.sendKeys(Keys.CONTROL + "a");
            maeGUIObjects.DEPARTURE_DATE_IN_GATE.sendKeys(Keys.BACK_SPACE);
            gl.inputText(maeGUIObjects.DEPARTURE_DATE_IN_GATE, departureDate);

            logInfo.info(MarkupHelper.createLabel("I select the origin city", ExtentColor.PURPLE));
            gl.clickElement(maeGUIObjects.ORGIN_CITY_IN_GATE);

            maeGUIObjects.ORGIN_CITY_IN_GATE.sendKeys(Keys.CONTROL + "a");
            maeGUIObjects.ORGIN_CITY_IN_GATE.sendKeys(Keys.BACK_SPACE);
            gl.inputText(maeGUIObjects.ORGIN_CITY_IN_GATE, origin);
            gl.waitProgress();
            gl.waitForProfileLoad();
            String xpath_OriginEnter = String.format("//li[@class='md-autocomplete-suggestion ng-scope selected']//span[@class='highlight' and contains(text(),'%s')]", origin);
            WebElement ORIGIN_ENTER_BTN = driver.get().findElement(By.xpath(xpath_OriginEnter));
            gl.clickElement(ORIGIN_ENTER_BTN);
            gl.waitProgress();
            gl.waitForProfileLoad();
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            logInfo.info(MarkupHelper.createLabel("I click on search button", ExtentColor.PURPLE));

            gl.clickElement(maeGUIObjects.FLIGHT_SEARCH_BUTTON_IN_GATE);
            waitUntilPageLoad(logInfo);

            gl.highLightErrorMessages(logInfo, "Unable to retrieve passenger","Error on physical connection");

            if (gl.existElement(maeGUIObjects.FLIGHT_NO_OPEN_ERROR_MSG)) {
                assignShipmentNumberToFlightInGUIInGatePage(Integer.parseInt(segmentIndex), logInfo);
                gl.waitProgress();
            }
            waitUntilPageLoad(logInfo);
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


    public void selectValueFromPNRDropDown(ExtentTest logInfo, String searchType) {

        try {
            gl.waitForProfileLoad();
            if (gl.existElement(maeGUIObjects.PRINTER_ACCEPT)) {
                maeGUIObjects.PRINTER_ACCEPT_BUTTON.click();
                gl.waitForProfileLoad();
                gl.waitForProfileLoad();
            }
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            logInfo.info(MarkupHelper.createLabel("I click on selections drop down", ExtentColor.PURPLE));
            gl.clickElement(maeGUIObjects.SEARCH_TYPE_SELECTION_DROPDOWN);
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            String xpath_SearchOptionSelection = String.format("//div[@class='ng-binding ng-scope' and contains(text(),'%s')]", searchType);
            WebElement SEARCH_TYPE = driver.get().findElement(By.xpath(xpath_SearchOptionSelection));
            logInfo.info(MarkupHelper.createLabel("I search type", ExtentColor.PURPLE));
            gl.clickElement(SEARCH_TYPE);

            gl.clickElement(maeGUIObjects.INPUT_SEARCH_VALUE);

            if (searchType.equalsIgnoreCase("pnr")) {

                maeGUIObjects.INPUT_SEARCH_VALUE.sendKeys(Keys.CONTROL + "a");
                maeGUIObjects.INPUT_SEARCH_VALUE.sendKeys(Keys.BACK_SPACE);
                gl.inputText(maeGUIObjects.INPUT_SEARCH_VALUE, pax.getPnr());

                List<WebElement> SEQELEMENT = driver.get().findElements(By.xpath("//div[contains(@class, 'pssgui-bold') and contains(@class, 'flex-5') and contains(., 'Seq')]"));
                if (gl.existElement(SEQELEMENT)) {

                    List<WebElement> li = maeGUIObjects.GATE_SEQUENCE_NUMBERS;

                    for (int i = 0; i < mPassengers.get(getDriverID()).size(); i++) {
                        int seqNo = Integer.parseInt(li.get(i).getText().trim());
                        mPassengers.get(getDriverID()).get(i).setSequenceNumber(seqNo);
                    }

                } else if (gl.existElement(maeGUIObjects.UNRECONCILED_ERROR_MESSAGE)) {
                    logInfo.fail("I verify No Passengers Found message is displayed");
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    Assert.fail("I verify No Passengers Found message is displayed");
                }

            } else if (searchType.equalsIgnoreCase("name")) {
                gl.inputText(maeGUIObjects.INPUT_SEARCH_VALUE, pax.getfName());
            }

            waitUntilPageLoad(logInfo);
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            if (gl.existElement(maeGUIObjects.GATE_CHECK_ALL_OPTIONS)) {
                maeGUIObjects.GATEPAGE_CHECK_ALL_OPTION.click();
                gl.waitProgress();

            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

    public void selectMassTransferType(ExtentTest logInfo, String transferType) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            logInfo.info(MarkupHelper.createLabel("I click on " + transferType, ExtentColor.PURPLE));
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            if (transferType.equalsIgnoreCase("outbound")) {
                gl.clickElement(maeGUIObjects.OUTBOUND_BTN);
                gl.highLightErrorMessages(logInfo, "Outbound request failed");
            } else if (transferType.equalsIgnoreCase("inbound")) {
                gl.clickElement(maeGUIObjects.INBOUND_BTN);
            } else if (transferType.equalsIgnoreCase("current")) {
                gl.clickElement(maeGUIObjects.CURRENT_BTN);
            }
            pax.setmassTransferType(transferType);

            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            waitUntilPageLoad(logInfo);
        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

