    public void selectValueFromPNRDropDownForSequence(ExtentTest logInfo, String dropdownValue, String seqNum) {
        try {
            waitUntilPageLoad(logInfo);
            gl.waitForProfileLoad();
            int seq = Integer.parseInt(seqNum);

            if (gl.existElement(maeGUIObjects.PRINTER_ACCEPT)) {
                maeGUIObjects.PRINTER_ACCEPT_BUTTON.click();
                gl.waitForProfileLoad();
                gl.waitForProfileLoad();
            }

            int paxIndex = Integer.parseInt(seqNum);

            Passenger pax = mPassengers.get(getDriverID()).get(paxIndex);
            logInfo.info(MarkupHelper.createLabel("I click on selections drop down", ExtentColor.PURPLE));
            gl.clickElement(maeGUIObjects.SEARCH_TYPE_SELECTION_DROPDOWN);
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            String xpath_SearchOptionSelection = String.format("//div[@class='ng-binding ng-scope' and contains(text(),'%s')]", dropdownValue);
            WebElement SEARCH_TYPE = driver.get().findElement(By.xpath(xpath_SearchOptionSelection));
            logInfo.info(MarkupHelper.createLabel("I search type", ExtentColor.PURPLE));
            gl.clickElement(SEARCH_TYPE);

            gl.clickElement(maeGUIObjects.INPUT_SEARCH_VALUE);

            if (dropdownValue.equalsIgnoreCase("sequence")) {

                maeGUIObjects.INPUT_SEARCH_VALUE.sendKeys(Keys.CONTROL + "a");
                maeGUIObjects.INPUT_SEARCH_VALUE.sendKeys(Keys.BACK_SPACE);
                int r = pax.getSequenceNumber(seq);
                gl.inputText(maeGUIObjects.INPUT_SEARCH_VALUE, String.valueOf(r));
            }
            waitUntilPageLoad(logInfo);
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            if (gl.existElement(maeGUIObjects.GATE_CHECK_ALL_OPTIONS)) {
                maeGUIObjects.GATEPAGE_CHECK_ALL_OPTION.click();
                gl.waitProgress();

            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }

    }


