    public void validateTicket(String s) {
        boolean TktFound = false;
        if (!isExchange || !isRefund) { //if it is an exchange scenario we ignore the hovering and directly go to the contains text
            for (WebElement doc : maeGUIObjects.SALES_ITEMS) {
                if (doc.getText().contains(s)) {
                    WebElement hov = doc.findElement(By.xpath("//span[@ng-repeat='payment in salesItem.agentSaleItem.payments']"));
                    Actions actions = new Actions(getDriver());
                    actions.moveToElement(hov).build().perform();
                    TktFound = true;
                    break;
                }
            }

            if (TktFound) {
                org.junit.Assert.assertTrue(gl.pageShouldContainsText(s));
            } else {
                org.junit.Assert.fail();
            }

        }
    }

