    public void selectPrinter(ExtentTest logInfo, String printer, String printerStatus) {
        try{

            List<String> availablePrinters = Arrays.asList(
                    "IN-PF2ST1T4",
                    "IN-5CD4316MPJ",
                    "US-5CD4377SFF",
                    "MAHAC-NB"
            );
            String printerType="";
            String status="";
            gl.waitForProfileLoad();
            maeGUIObjects.CLICK_PRINTER_ICON.click();
            gl.waitProgress();
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            List<WebElement> selectPrinter= maeGUIObjects.CLICK_SELECT_BUTTON_PRINTER_POP_UP;
            for(WebElement element: selectPrinter){
                element.click();
                gl.waitProgress();
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                List<WebElement> printers= maeGUIObjects.PRINTER_TYPES;
                for(int i=0; i<printers.size(); i++){
                    String printerNameUI = printers.get(i).getText().trim();
                    printerType=  printers.get(i).getText().trim();

                    String xpath_Status = "(//div[@class='printer-status pssgui-bold layout-align-start-center layout-row flex'])["+(i+1)+"]";
                    WebElement pStatus = driver.get().findElement(By.xpath(xpath_Status));
                    status= pStatus.getText().trim();
                    // Match any printer name from the list AND check status
                    boolean nameMatches = availablePrinters.stream()
                            .anyMatch(name -> printerNameUI.toLowerCase().contains(name.toLowerCase()));
                    if(nameMatches && status.equalsIgnoreCase(printerStatus)){

                        logInfo.info(MarkupHelper.createLabel("I select the Printer to print Passenger Details", ExtentColor.PURPLE));
                        String ele1_Status = "(//md-radio-group[@ng-model='changePrinter.selectedPrinter']//div[@class='md-container md-ink-ripple'])["+(i+1)+"]";
                        WebElement ele1 = driver.get().findElement(By.xpath(ele1_Status));
                        ele1.click();
                        logInfo.pass(MarkupHelper.createLabel("Printer is ready to print the Status", ExtentColor.GREEN));
                        logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                        break;
                    }
                }

                if(!printerType.contains(printer) && !status.equalsIgnoreCase(printerStatus)){
                    logInfo.fail("Printer is not Ready to Print");
                    Assert.fail("Printer is not Ready");
                }

                gl.waitForProfileLoad();
                maeGUIObjects.SELECT_PRINTER_POPUP_OK_BUTTON.click();
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            }

            maeGUIObjects.PRINTER_POPUP_CLOSE.click();
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
        }
        catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            org.junit.Assert.fail("This step failed.. so stopping...");
        }
    }



