    public void seatAssign(ExtentTest logInfo) {

        try {
            List<WebElement> ALL_AVAILABLE_SEATS_ECONOMY = driver.get().findElements(By.xpath("//div[@class='seat-holder ng-scope']"));
            List<WebElement> ALL_AVAILABLE_SEATS_BUSINESS = driver.get().findElements(By.xpath("//div[@class='seat-holder ng-scope business-seat']"));
            if (gl.existElement(ALL_AVAILABLE_SEATS_ECONOMY) || gl.existElement(maeGUIObjects.AVAILABLE_SEATS)) {
                if (gl.existElement(ALL_AVAILABLE_SEATS_ECONOMY)) {
                    for (WebElement seat : ALL_AVAILABLE_SEATS_ECONOMY) {
                        seat.click();
                        gl.waitProgress();
                        gl.waitForProfileLoad();
                        break;
                    }
                } else if (gl.existElement(maeGUIObjects.AVAILABLE_SEATS)) {
                    for (WebElement seat : maeGUIObjects.AVAILABLE_SEATS) {
                        seat.click();
                        gl.waitProgress();
                        gl.waitForProfileLoad();
                        break;
                    }
                }
            } else {
                if (gl.existElement(ALL_AVAILABLE_SEATS_BUSINESS)) {
                    for (WebElement seat : ALL_AVAILABLE_SEATS_BUSINESS) {
                        seat.click();
                        gl.waitProgress();
                        gl.waitForProfileLoad();
                        break;
                    }
                } else if (gl.existElement(maeGUIObjects.AVAILABLE_SEATS_BUSINESS)) {
                    for (WebElement seat : maeGUIObjects.AVAILABLE_SEATS_BUSINESS) {
                        seat.click();
                        gl.waitProgress();
                        gl.waitForProfileLoad();
                        break;
                    }
                }
            }
        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }

    }


