    public void selectCitiesForSixthSegment(String from, String to, ExtentTest logInfo) {
        try {
            for (Passenger pax : mPassengers.get(getDriverID())) {
                pax.setSegmentOriginCity(5, from);
                pax.setSegmentDestinationCity(5, to);
            }

            maeGUIObjects.ADD_SEGMENT.click();
            do {

                maeGUIObjects.INPUT_ORIGIN_CITY_6.clear();
                maeGUIObjects.INPUT_ORIGIN_CITY_6.sendKeys(from);
                gl.waitForProfileLoad();
                maeGUIObjects.INPUT_ORIGIN_CITY_6.sendKeys(Keys.ENTER);
                gl.waitForProfileLoad();
            } while (maeGUIObjects.INPUT_ORIGIN_CITY_2_ERROR.size() > 0);

            do {
                maeGUIObjects.INPUT_DESTINATION_CITY_6.clear();
                maeGUIObjects.INPUT_DESTINATION_CITY_6.sendKeys(to);
                gl.waitForProfileLoad();
                maeGUIObjects.INPUT_DESTINATION_CITY_6.sendKeys(Keys.ENTER);
                gl.waitForProfileLoad();
            } while (maeGUIObjects.INPUT_DESTINATION_CITY_2_ERROR.size() > 0);

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }

    }


