    public void search2ndPNROrderScreenToCheckStatusInTicketTab(ExtentTest logInfo, String ticketStatus) {

        Passenger pax = mPassengers.get(getDriverID()).get(0);
        String pnr = pax.getPnr2();
        String value = "";
        try {
            gl.waitForProfileLoad();
            maeGUIObjects.btn_Reservations.click();

            gl.waitProgress();
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            for (int i = 0; i < 50; i++) {
                gl.waitForProfileLoad();
                gl.clickElement(maeGUIObjects.SEARCH_TEXTAREA);
                maeGUIObjects.SEARCH_TEXTAREA.sendKeys(pnr);
                gl.waitForProfileLoad();
                gl.clickButton(maeGUIObjects.SEARCH_ICON);
                gl.waitProgress();
                gl.waitForProfileLoad();
                gl.waitForElementAfterReload(getDriver(), maeGUIObjects.ORDER_TAB, PAGE_LOAD_TIMEOUT);

                gl.clickElement(maeGUIObjects.TICKETS_TAB1);
                gl.waitForProfileLoad();

                if (ticketStatus.equalsIgnoreCase("CHECKED-IN")) {
                    List<WebElement> status = maeGUIObjects.TICKET_CHECKIN_STATUS;

                    for (WebElement text : status) {
                        value = text.getText();

                        if (value.equalsIgnoreCase(ticketStatus)) {
                            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                            System.out.println(ticketStatus + " element is visible");
                            break;
                        }
                    }
                } else if (ticketStatus.equalsIgnoreCase("Open")) {

                    List<WebElement> status = maeGUIObjects.TICKET_OPEN_STATUS;
                    for (WebElement text : status) {
                        value = text.getText();

                        if (value.equalsIgnoreCase(ticketStatus)) {
                            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                            System.out.println(ticketStatus + " element is visible");
                            break;
                        }
                    }
                } else if (ticketStatus.equalsIgnoreCase("VOIDED")) {
                    List<WebElement> status = maeGUIObjects.TICKET_VOIDED_STATUS;
                    for (WebElement text : status) {
                        value = text.getText();

                        if (value.equalsIgnoreCase(ticketStatus)) {
                            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                            System.out.println(ticketStatus + " element is visible");
                            break;
                        }
                    }
                } else if (ticketStatus.equalsIgnoreCase("NOSHOWED")) {
                    List<WebElement> status = maeGUIObjects.TICKET_NOSHOWED_STATUS;
                    for (WebElement text : status) {
                        value = text.getText();

                        if (value.equalsIgnoreCase(ticketStatus)) {
                            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                            System.out.println(ticketStatus + " element is visible");
                            break;
                        }
                    }

                } else if (ticketStatus.equalsIgnoreCase("ADJUSTED")) {
                    List<WebElement> status = maeGUIObjects.TICKET_ADJUSTED_STATUS;
                    for (WebElement text : status) {
                        value = text.getText();

                        if (value.equalsIgnoreCase(ticketStatus)) {
                            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                            System.out.println(ticketStatus + " element is visible");
                            break;
                        }
                    }

                } else if (ticketStatus.equalsIgnoreCase("CM USED")) {

                    List<WebElement> status = maeGUIObjects.TICKET_CM_USED_STATUS;
                    for (WebElement text : status) {
                        value = text.getText();

                        if (value.equalsIgnoreCase(ticketStatus)) {
                            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                            System.out.println(ticketStatus + " element is visible");
                            break;
                        }
                    }
                }

                if (value.equalsIgnoreCase(ticketStatus)) {
                    break;
                }

            }
        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");

        }
    }


