            String splitInfo = "//div[@translate='pssgui.split.info']";
            WebElement SPLIT_INFO = driver.get().findElement(By.xpath(splitInfo));
            SPLIT_INFO.click();
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            String secondPNR = "//td[@ng-click=\"splitBooking.stateChange(booking.OrderID, 'order')\"]";
