    public void retrieveThePNRAfterSplittingThePNR(ExtentTest logInfo) {
        ArrayList<Passenger> paxList = mPassengers.get(getDriverID());
        String paxCount = Integer.toString(paxList.size());
        Passenger pax = mPassengers.get(getDriverID()).get(0);
        String pnr = pax.getPnr();
        try {
            gl.waitForProfileLoad();

            for (int i = 0; i < 20; i++) {
                gl.waitForProfileLoad();
                gl.clickElement(maeGUIObjects.SEARCH_TEXTAREA);
                maeGUIObjects.SEARCH_TEXTAREA.sendKeys(pnr);
                gl.waitForProfileLoad();
                gl.clickButton(maeGUIObjects.SEARCH_ICON);
                gl.waitProgress();
                gl.waitForProfileLoad();
                gl.waitForElementAfterReload(getDriver(), maeGUIObjects.ORDER_TAB, PAGE_LOAD_TIMEOUT);
                String xpath_NumberOfPaxInPNR = "(//span[contains(@class, 'pssgui-design-value-2') and contains(@class, 'ng-binding')])[1]";
                WebElement NUMBER_OF_PASSENGER_IN_FIRST_PNR = driver.get().findElement(By.xpath(xpath_NumberOfPaxInPNR));
                String xpath_NumberOfINFPaxInPNR = "(//span[contains(@class, 'pssgui-design-value-2') and contains(@class, 'ng-binding')])[2]";
                WebElement NUMBER_OF_INFPASSENGER_IN_FIRST_PNR = driver.get().findElement(By.xpath(xpath_NumberOfINFPaxInPNR));
                String countInPNR;
                String countOfINFInPNR;

                if (pax.getpnrType().contains("Group") || pax.getpnrType().contains("Corporate")) {
                    countInPNR = NUMBER_OF_PASSENGER_IN_FIRST_PNR.getText().trim();
                    String noOfINFPaxInGroupPNR = "//span[@class='pssgui-design-value-2 margin-right ng-binding']";
                    WebElement NO_OF_INF_PAX_IN_GROUP_PNR = driver.get().findElement(By.xpath(noOfINFPaxInGroupPNR));
                    countOfINFInPNR = NO_OF_INF_PAX_IN_GROUP_PNR.getText();
                } else {
                    countInPNR = NUMBER_OF_PASSENGER_IN_FIRST_PNR.getText().trim();
                    countOfINFInPNR = NUMBER_OF_INFPASSENGER_IN_FIRST_PNR.getText().trim();
                }
                int TotalPaxInPNR = Integer.parseInt(countInPNR) + Integer.parseInt(countOfINFInPNR);
                if (!(Integer.toString(TotalPaxInPNR)).equals(paxCount)) {
                    gl.waitProgress();
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    break;
                }
            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

