    public void addStandardBaggageForAllPassengers(ExtentTest logInfo) {
        try {
            ArrayList<Passenger> paxList = mPassengers.get(getDriverID());
            for (int j = 1; j <=paxList.size(); j++) {
                String xpath = "(//span[contains(@class, 'icon-value ng-binding')])[" + j + "]";
                WebElement bagIcon = driver.get().findElement(By.xpath(xpath));
                logInfo.info(MarkupHelper.createLabel("I click on bag icon", ExtentColor.PURPLE));
                gl.clickElement(bagIcon);
                gl.waitProgress();
                gl.waitForProfileLoad();
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                //Selection of baggage type drop down
                logInfo.info(MarkupHelper.createLabel("I select the baggage type as standard", ExtentColor.PURPLE));
                gl.clickElement(maeGUIObjects.BAG_TYPE_SELECTION_DROPDOWN);
                gl.clickElement(maeGUIObjects.BAGGAGE_STANDARD);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                Passenger pax = mPassengers.get(getDriverID()).get(0);
                String baggageWeight = String.valueOf(pax.getBaggageWeight());
                int totagBags = pax.getTotalBags();

                //Adding weight of the baggage

                if (totagBags == 1) {
                    logInfo.info(MarkupHelper.createLabel("I input the bag weight as: "+baggageWeight , ExtentColor.PURPLE));
                    gl.clickElement(maeGUIObjects.INPUT_WEIGHT);
                    gl.waitForProfileLoad();
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    gl.inputText(maeGUIObjects.INPUT_WEIGHT, baggageWeight);
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                } else if (totagBags > 1) {
                    //Adding the first bag
                    logInfo.info(MarkupHelper.createLabel("I input the bag weight as: "+baggageWeight , ExtentColor.PURPLE));
                    gl.clickElement(maeGUIObjects.INPUT_WEIGHT);
                    gl.waitForProfileLoad();
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    gl.inputText(maeGUIObjects.INPUT_WEIGHT, baggageWeight);
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    for (int i = 2; i <= totagBags; i++) {
                        logInfo.info(MarkupHelper.createLabel("I add another bag - "+ i , ExtentColor.PURPLE));
                        gl.clickElement(maeGUIObjects.ADD_ANOTHER_BAGGAGE);

                        //Adding weights for the next baggage
                        String xpath_Weights = "(//input[@aria-label='Weight'])[" + i + "]";
                        WebElement INPUT_NEXT_WEIGHT = driver.get().findElement(By.xpath(xpath_Weights));
                        logInfo.info(MarkupHelper.createLabel("I input the bag weight as: "+totagBags , ExtentColor.PURPLE));
                        gl.clickElement(INPUT_NEXT_WEIGHT);
                        gl.waitForProfileLoad();
                        logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                        gl.inputText(INPUT_NEXT_WEIGHT, baggageWeight);
                        logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    }
                }
                logInfo.info(MarkupHelper.createLabel("I click on submit button" , ExtentColor.PURPLE));
                gl.clickElement(maeGUIObjects.BAGGAGE_SUBMIT);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                gl.waitProgress();
                gl.waitForProfileLoad();
                //Payment for baggage added
                if (maeGUIObjects.BAGGAGE_PROCEED_TO_PAY.isEnabled()) {
                    logInfo.info(MarkupHelper.createLabel("I click on proceed to pay button to do the payment" , ExtentColor.PURPLE));
                    gl.clickElement(maeGUIObjects.BAGGAGE_PROCEED_TO_PAY);
                    gl.waitProgress();
                    gl.waitForProfileLoad();
                    String paymentType = pax.getPaymentType(0);
                    String amount = maeGUIObjects.INPUT_AMOUNT.get(0).getAttribute("value");
                    pax.setPaymentAmount(amount);
                    makeFirstPayment(paymentType, logInfo);
                    gl.waitProgress();
                    gl.waitForProfileLoad();
                    List <WebElement> FOID= driver.get().findElements(By.xpath("//md-select[@aria-label='Document Type']"));
                    if(gl.existElement(FOID)) {
                        enterFOIDDetailsWithSpecifiedDocumentType(logInfo, paxList.get(0).getFOIDType());
                    }
                    gl.waitProgress();
                    gl.waitForProfileLoad();
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    logInfo.info(MarkupHelper.createLabel("I click done button" , ExtentColor.PURPLE));
                    clickOnDoneButton(logInfo);
                    gl.waitProgress();
                    gl.waitForProfileLoad();
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    logInfo.info(MarkupHelper.createLabel("I click continue button" , ExtentColor.PURPLE));
                    clickOnContinueButton(logInfo);
                }
                else{
                    gl.waitProgress();
                    gl.waitForProfileLoad();
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    logInfo.info(MarkupHelper.createLabel("I click continue button" , ExtentColor.PURPLE));
                    clickOnContinueButton(logInfo);
                }
            }
        }
        catch (AssertionError | Exception e)
        {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            org.junit.Assert.fail("This step failed.. so stopping...");
        }
    }


