    public void seatSelectionFromServicesTab(ExtentTest logInfo) {
        try {

            if (!gl.pageShouldContainsText("No Seatmap Available for Selected Flight")) {
                //Select the seat in the seat map
                for (WebElement passengers : maeGUIObjects.LIST_OF_PASSENGERS) {
                    int j = 0;
                    for (WebElement segments : maeGUIObjects.SEATMAP_SEGMENTS) {
                        gl.clickElement(passengers);
                        if (j == 0) {
                            if (gl.verifyIsCheckboxSelected(maeGUIObjects.SEATMAP_SEGMENTS_CHECKBOX1)) {
                                seatAssign(logInfo);
                            } else {
                                maeGUIObjects.SEATMAP_SEGMENTS_CHECKBOX.get(j).click();
                                gl.waitProgress();
                                gl.waitForProfileLoad();
                                logInfo.pass("I select the segment checkbox");
                                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                            }
                            gl.clickElement(passengers);
                            seatAssign(logInfo);
                            j++;
                            logInfo.pass("I select the seat for single segment");
                            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                        }
                        gl.waitForProfileLoad();
                    }
                }
                //Click on submit button
                if (maeGUIObjects.AVAILABLE_SEATS_SUBMIT.isEnabled()) {
                    maeGUIObjects.AVAILABLE_SEATS_SUBMIT.click();
                    gl.waitProgress();
                    gl.waitForProfileLoad();
                    logInfo.pass("I select the seats");
                }

                //Click on add to order
                if (gl.existElement(maeGUIObjects.ADD_TO_ORDER1)) {
                    logInfo.pass("I select the seats");
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    gl.clickElement(maeGUIObjects.ADD_TO_ORDER);
                    gl.waitProgress();
                    gl.waitForProfileLoad();
                }
            } else {
                logInfo.fail(MarkupHelper.createLabel("Seat map currently not available.Please check again later", ExtentColor.RED));
                org.junit.Assert.fail("This step failed.. so stopping...");
            }
        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


