    public void storeTicketNumberForConjunctiveSegments(ExtentTest logInfo) {
        try {

            ArrayList<Passenger> pax = mPassengers.get(getDriverID());
            gl.waitForProfileLoad();
            gl.clickElement(maeGUIObjects.TICKETS_TAB1);
            gl.waitProgress();
            gl.waitForProfileLoad();
            List<WebElement> couponSize = maeGUIObjects.TICKETS_TAB_COUPON;
            List<WebElement> paxSize = maeGUIObjects.TICKETS_TAB_PASSENGER_COUNT;
            List<WebElement> couponsLink = maeGUIObjects.TICKET_TAB_COUPONS_LINK;

            for (WebElement element : couponSize) {
                gl.scrollToWebElement(element);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            }

            for (int j = 0; j < pax.size(); j++) {
                gl.scrollToWebElement(paxSize.get(j));
                gl.waitForProfileLoad();
                if (j == 0) {
                    gl.scrollToWebElement(couponSize.get(j));

                    String ticketNumber = couponsLink.get(j).getText();
                    pax.get(j).setConjuctiveTicketNumbers(0, ticketNumber);
                    gl.scrollToWebElement(couponSize.get(j + 1));
                    ticketNumber = couponsLink.get(j + 1).getText();
                    pax.get(j).setConjuctiveTicketNumbers(1, ticketNumber);
                }
                if (j == 1) {
                    gl.scrollToWebElement(couponSize.get(j + 1));
                    String ticketNumber = couponsLink.get(j + 1).getText();
                    pax.get(j).setConjuctiveTicketNumbers(0, ticketNumber);
                    gl.scrollToWebElement(couponSize.get(j + 2));
                    ticketNumber = couponsLink.get(j + 2).getText();
                    pax.get(j).setConjuctiveTicketNumbers(1, ticketNumber);
                }
                if (j == 2) {
                    gl.scrollToWebElement(couponSize.get(j + 2));
                    String ticketNumber = couponsLink.get(j + 2).getText();
                    pax.get(j).setConjuctiveTicketNumbers(0, ticketNumber);
                    gl.scrollToWebElement(couponSize.get(j + 3));
                    ticketNumber = couponsLink.get(j + 3).getText();
                    pax.get(j).setConjuctiveTicketNumbers(1, ticketNumber);
                }
                if (j == 3) {
                    gl.scrollToWebElement(couponSize.get(j + 3));
                    String ticketNumber = couponsLink.get(j + 3).getText();
                    pax.get(j).setConjuctiveTicketNumbers(0, ticketNumber);
                    gl.scrollToWebElement(couponSize.get(j + 4));
                    ticketNumber = couponsLink.get(j + 4).getText();
                    pax.get(j).setConjuctiveTicketNumbers(1, ticketNumber);
                }

            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }

    }


