    public void selectAllFlightForAvailability(String cabin, ExtentTest logInfo) {

        int segmentsToCheck = 2;

        for (int i = 2; i < maeGUIObjects.FLIGHTS_AVAILABLE.size(); i = i + 2) {
            maeGUIObjects.FLIGHTS_AVAILABLE.get(i).click();
            gl.waitProgress();
            if (cabin.equalsIgnoreCase("Economy")) {
                returnFullEconomyAvailability(logInfo, segmentsToCheck);
            } else if (cabin.equalsIgnoreCase("Business")) {
                returnFullBusinessAvailability(logInfo, segmentsToCheck);
            }
            segmentsToCheck++;
        }

    }


