    public void clickOnSeatIconAndAddSeatsInCheckinPage(ExtentTest logInfo) {
        try {
            ArrayList<String> paxSeatNumbers;
            maeGUIObjects.SEAT_ICON.click();
            gl.waitProgress();
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            if (gl.existElement(maeGUIObjects.SEATMAP_ERROR_PANEL)) {
                logInfo.info(MarkupHelper.createLabel("Seat map currently not available. Please check again later", ExtentColor.PURPLE));
                Assert.fail("Seat map currently not available");
            }

            for (int i = 0; i < maeGUIObjects.SEATMAP_SEGMENTS_CHECKBOX.size(); i++) {
                maeGUIObjects.SEATMAP_SEGMENTS_CHECKBOX.get(i).click();

                if (i == 0)                                                         //The first checkbox will be selected by default, that is why we are clicking on it twice to deselect and select it again
                    maeGUIObjects.SEATMAP_SEGMENTS_CHECKBOX.get(i).click();

                for (int j = 0; j < maeGUIObjects.LIST_OF_PASSENGERS.size(); j++) {
                    maeGUIObjects.LIST_OF_PASSENGERS.get(j).click();

                    if (gl.existElement(maeGUIObjects.AVAILABLE_SEATS)) {
                        for (WebElement seat : maeGUIObjects.AVAILABLE_SEATS) {
                            seat.click();
                            gl.waitForProfileLoad();
                            break;
                        }
                    }
                }
            }
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            for (int i = 0; i < maeGUIObjects.SEATMAP_SEGMENTS_CHECKBOX.size(); i++) {
                paxSeatNumbers = new ArrayList<>();
                maeGUIObjects.SEATMAP_SEGMENTS_CHECKBOX.get(i).click();

                for (WebElement seat : maeGUIObjects.SEAT_NUMBERS) {
                    paxSeatNumbers.add(seat.getAttribute("value"));
                }

                int j = 0;
                for (String seatNo : paxSeatNumbers) {
                    Passenger pax = mPassengers.get(getDriverID()).get(j++);
                    if (pax.getSeatNumber() == null)
                        pax.setSeatNumber(seatNo);
                    else
                        pax.setSeatNumber(pax.getSeatNumber() + "*" + seatNo + "*");
                }
            }

            for (int i = 0; i < mPassengers.get(getDriverID()).size(); i++) {
                System.out.println("Seat numbers: " + mPassengers.get(getDriverID()).get(i).getSeatNumber());
            }

            maeGUIObjects.SUBMIT_BUTTON.click();
            gl.waitProgress();

            maeGUIObjects.CLICK_CONTINUE_BUTTON.click();
            gl.waitProgress();

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

