    public void enterFOIDDetailsWithSpecifiedDocumentType(ExtentTest logInfo, String documentType) {
        try {
            for (WebElement webElement : maeGUIObjects.PASSENGER_SELECT) {
                for (int i = 0; i < maeGUIObjects.PASSENGER_SELECT.size(); i++) {
                    Passenger pax = mPassengers.get(getDriverID()).get(i);
                    webElement.click();
                    gl.waitForProfileLoad();

                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                    maeGUIObjects.FOID_DOCUMENT_TYPE_DROPDOWN.click();
                    gl.waitForProfileLoad();
                    String documentType_xpath = String.format("//md-option//div[@class='md-text ng-binding' and contains(text(),'%s')]", documentType);
                    WebElement DOCUMENT_TYPE_SELECTION = driver.get().findElement(By.xpath(documentType_xpath));
                    gl.clickElement(DOCUMENT_TYPE_SELECTION);
                    gl.waitProgress();
                    gl.waitForProfileLoad();
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                    if (documentType.equalsIgnoreCase("National Identification Card")) {
                        gl.inputText(maeGUIObjects.INPUT_STATECODE, "US");
                        gl.waitProgress();
                        gl.waitForProfileLoad();
                        gl.inputText(maeGUIObjects.INPUT_NUMBER, "198765");
                        gl.waitProgress();
                        gl.waitForProfileLoad();

                    } else if (documentType.equalsIgnoreCase("Drivers License")) {
//                    gl.clickElement(maeGUIObjects.OPTION_DRIVERS_LICENSE);
                        gl.inputText(maeGUIObjects.INPUT_STATECODE, "US");
                        gl.waitProgress();
                        gl.waitForProfileLoad();
                        gl.inputText(maeGUIObjects.INPUT_NUMBER, "198764");
                        gl.waitProgress();
                        gl.waitForProfileLoad();
                    } else if (documentType.equalsIgnoreCase("Passport")) {
//                    gl.clickElement(maeGUIObjects.OPTION_PASSPORT);
                        gl.inputText(maeGUIObjects.INPUT_STATECODE, "US");
                        gl.waitProgress();
                        gl.waitForProfileLoad();
                        gl.inputText(maeGUIObjects.INPUT_NUMBER, "P19876434");
                        gl.waitProgress();
                        gl.waitForProfileLoad();
                    }
                    pax.setFOIDType(documentType);
                }
            }
            List<WebElement> NEXTBUTTON = driver.get().findElements(By.xpath("//button[contains(@ng-click, 'foid') and normalize-space(text())='Next']"));
            List<WebElement> PAYBUTTON = driver.get().findElements(By.xpath("//button[normalize-space(text())='Pay' and contains(@ng-click, 'foid.stateChange')]"));
            if (gl.existElement(maeGUIObjects.FOID_PAY)) {
                gl.clickElement(maeGUIObjects.FOID_PAY_BUTTON);
                gl.waitProgress();
                gl.waitForProfileLoad();
            } else if (gl.existElement(NEXTBUTTON)) {
                gl.scrollToWebElement(maeGUIObjects.FOID_NEXT_BUTTON);
                gl.clickButton(maeGUIObjects.FOID_NEXT_BUTTON);
                gl.waitProgress();
                gl.waitForProfileLoad();
            } else if (gl.existElement(PAYBUTTON)) {
                gl.clickElement(maeGUIObjects.PAYMENT_PAY_BUTTON);
                gl.waitProgress();
                gl.waitForProfileLoad();
            }


        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }

    }


    private boolean isAllowedEconomyClass(String label) {
        String[] allowedClasses = {"Y", "B", "M", "H", "Q", "K", "V", "U", "S", "O", "W", "E", "L", "T", "A"};
        for (String cls : allowedClasses) {
            if (label.contains(cls)) {
                return true;
            }
        }
        return false;
    }

    private boolean isAllowedBusinessClass(String label) {
        String[] allowedClasses = {"C", "J", "D", "R"};
        for (String cls : allowedClasses) {
            if (label.contains(cls)) {
                return true;
            }
        }
        return false;
    }



