    public void checkTheRemarksFromOderTab(ExtentTest logInfo, String remarkType) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);

            gl.clickElement(maeGUIObjects.SEARCH_MENU);
            maeGUIObjects.ITINERARY_INPUT_TEXT.sendKeys(pax.getPnr());
            gl.waitForProfileLoad();
            gl.clickButton(maeGUIObjects.SEARCH_ORDER_BUTTON);
            gl.waitForProfileLoad();
            gl.waitForElementAfterReload(getDriver(), maeGUIObjects.ORDER_TAB, PAGE_LOAD_TIMEOUT);
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            gl.clickElement(maeGUIObjects.REMARKS_LINK);
            gl.waitForProfileLoad();

            for (int i = 1; i <= maeGUIObjects.REMOVE_ICONS_IN_REMARKS.size(); i++) {
                if (i == maeGUIObjects.REMOVE_ICONS_IN_REMARKS.size() / 2) {
                    String xpath_removeIcon1 = "(//span[contains(@class, 'remark-action') and contains(@class, 'ng-scope')]/i[contains(@class, 'icon-removed')])[" + i + "]";
                    WebElement removeIcon1 = driver.get().findElement(By.xpath(xpath_removeIcon1));
                    gl.scrollToWebElement(removeIcon1);
                    gl.waitForProfileLoad();
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                }
                if (i == maeGUIObjects.REMOVE_ICONS_IN_REMARKS.size()) {
                    String xpath_removeIcon2 = "(//span[contains(@class, 'remark-action') and contains(@class, 'ng-scope')]/i[contains(@class, 'icon-removed')])[" + i + "]";
                    WebElement removeIcon2 = driver.get().findElement(By.xpath(xpath_removeIcon2));
                    gl.scrollToWebElement(removeIcon2);
                    gl.waitForProfileLoad();
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                }
            }
            if (remarkType.equalsIgnoreCase("baggagetransfer")) {
                String xpathBag = "//div[@class='pssgui-link ng-binding' and contains(text(),'CBAG')]";
                List<WebElement> baggageTransfer = driver.get().findElements(By.xpath(xpathBag));
                if (!gl.existElement(baggageTransfer)) {
                    Assert.fail("Baggage Transfer Remark not available");
                }

            } else if (remarkType.equalsIgnoreCase("InvoluntaryReissue")) {
                String xpathInvolReissue = "//div[@class='pssgui-link ng-binding' and contains(text(),'INVOL REISSUE')]";
                List<WebElement> InvolReissue = driver.get().findElements(By.xpath(xpathInvolReissue));
                if (!gl.existElement(InvolReissue)) {
                    Assert.fail("Involuntary Reissue Remark not available");
                }

            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

