    public void selectADCBypassGiveReason(ExtentTest logInfo, String reason) {
        try {

            String listValue;
            gl.waitForProfileLoad();
            gl.waitProgress();
            gl.clickElement(maeGUIObjects.CLICK_ADC_BYPASS_CHECK_BOX);
            gl.waitForProfileLoad();
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            gl.clickElement(maeGUIObjects.CLICK_BYPASS_DROP_DOWN);
            gl.waitForProfileLoad();
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            List<WebElement> adcList = maeGUIObjects.ADC_DROP_DOWN_LIST;
            for (WebElement list : adcList) {
                listValue = list.getText();
                if (listValue.equalsIgnoreCase(reason)) {
                    list.click();
                    break;
                }
            }

            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            gl.waitProgress();
            gl.waitForProfileLoad();
            gl.clickElement(maeGUIObjects.ADC_BYPASS_OK_BUTTON);
            gl.waitProgress();
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");


        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


    public void addBaggageCountAndWeight(String baggageNo, String baggageWeight, ExtentTest logInfo) {
        try {
            gl.waitProgress();
            gl.waitForProfileLoad();
            String xpath_Weights = "(//input[@aria-label='Weight'])[" + baggageNo + "]";
            WebElement INPUT_NEXT_WEIGHT = driver.get().findElement(By.xpath(xpath_Weights));
            gl.clickElement(INPUT_NEXT_WEIGHT);
            gl.waitProgress();
            gl.waitForProfileLoad();
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            JavascriptExecutor js = (JavascriptExecutor) getDriver();
            js.executeScript(
                    "arguments[0].value='" + baggageWeight + "';" +
                            "arguments[0].dispatchEvent(new Event('input', { bubbles: true }));" +
                            "arguments[0].dispatchEvent(new Event('change', { bubbles: true }));",
                    INPUT_NEXT_WEIGHT
            );

            logInfo.pass("I input the bag weight as: " + baggageWeight);
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

