                    gl.waitForProfileLoad();
                    maeGUIObjects.COMPENSATION_REASON_DROP_DOWN.click();

                    String xpath_SearchOptionSelection = String.format("//div[@class='md-text ng-binding' and contains(text(),'%s')]", reason);
