    public void selectSpecificSeats(ExtentTest logInfo, String seatToBook, String seatToCheck) {

        int pcount, maxSeats = 2, businessMax = 0;
        try {
            Dates:
            for (WebElement NextDt : maeGUIObjects.CAROUSEL_NEXT_DATES) {

                FlightSegment:
                for (WebElement segment : maeGUIObjects.SEGMENT_FLIGHTS) {
                    WebElement flightNo = segment.findElement(By.xpath(".//div[@class='ng-binding']"));
                    List<WebElement> Code_Share = segment.findElements(By.xpath(".//div[@translate='pssgui.codeshare.flight']"));

                    if (flightNo.getText().length() >= 4 && (flightNo.getText().contains("CM") || flightNo.getText().contains("UA")) && (Code_Share.size() != 1)) {
                        List<WebElement> seats = segment.findElements(By.xpath(".//span[contains(@class, 'small-box')]"));

//                        boolean seatClick=false;
                        for (WebElement seat : seats) {
                            String label = seat.getText();
                            pcount = label.length() == 2 ? Integer.parseInt(String.valueOf(label.charAt(1))) : Integer.parseInt(String.valueOf(label.charAt(2)));
                            if (label.contains(seatToCheck) && (pcount >= maxSeats)) {
                                gl.scrollToWebElement(seat);
                                String seatNum = label.substring(1);
                                int seatno = Integer.parseInt(seatNum);
                                if (seatno != 0) {
                                    List<WebElement> seats1 = segment.findElements(By.xpath(".//span[contains(@class, 'small-box')]"));
                                    for (WebElement seat1 : seats1) {
                                        String label1 = seat1.getText();
                                        pcount = label1.length() == 2 ? Integer.parseInt(String.valueOf(label1.charAt(1))) : Integer.parseInt(String.valueOf(label1.charAt(2)));
                                        if (label1.contains(seatToBook) && (pcount >= maxSeats)) {
                                            seat1.click();
//                                            seatClick=true;
                                            break;
                                        }
                                    }
                                }
                                if (maeGUIObjects.REMOVE_ICONS_AVAILABLE.size() >= 1) {
                                    break;
                                }
                            }
                        }
                        if (maeGUIObjects.REMOVE_ICONS_AVAILABLE.size() >= 1) {
                            break Dates;
                        }
                    }
                }
                maeGUIObjects.CAROUSEL_RIGHT_ARROW.click();
                NextDt.click();
                gl.waitProgress();
            }
        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


    public void selectSpecificSeatsForReturnFlight(ExtentTest logInfo, String seatToBook, String seatToCheck) {

        int segmentsToCheck = 2;

        for (int i = 2; i < maeGUIObjects.FLIGHTS_AVAILABLE.size(); i = i + 2) {
            maeGUIObjects.FLIGHTS_AVAILABLE.get(i).click();
            gl.waitProgress();
            returnSpecificSeat(logInfo, seatToBook, seatToCheck, segmentsToCheck);
            segmentsToCheck++;
        }

    }


    public void returnSpecificSeat(ExtentTest logInfo, String seatToBook, String seatToCheck, int segmentsToCheck) {
        int pcount;
        int passengerCount = mPassengers.get(getDriverID()).size();

        try {

            Dates:
            for (WebElement NextDt : maeGUIObjects.CAROUSEL_NEXT_DATES) {
                FlightSegment:
                for (WebElement segment : maeGUIObjects.SEGMENT_FLIGHTS) {
                    WebElement flightNo = segment.findElement(By.xpath(".//div[@class='ng-binding']"));
                    List<WebElement> Code_Share = segment.findElements(By.xpath(".//div[@translate='pssgui.codeshare.flight']"));

                    if (flightNo.getText().length() >= 4 && (flightNo.getText().contains("CM") || flightNo.getText().contains("UA")) && (Code_Share.size() != 1)) {
                        List<WebElement> seats = segment.findElements(By.xpath(".//span[contains(@class, 'small-box')]"));

                        for (WebElement seat : seats) {
                            String label = seat.getText();
                            pcount = label.length() == 2 ? Integer.parseInt(String.valueOf(label.charAt(1))) : Integer.parseInt(String.valueOf(label.charAt(2)));

                            if (label.contains(seatToCheck) && (pcount >= passengerCount)) {
                                gl.scrollToWebElement(seat);
                                String seatNum = label.substring(1);
                                int seatno = Integer.parseInt(seatNum);
                                if (seatno != 0) {
                                    List<WebElement> seats1 = segment.findElements(By.xpath(".//span[contains(@class, 'small-box')]"));
                                    for (WebElement seat1 : seats1) {
                                        String label1 = seat1.getText();
                                        pcount = label1.length() == 2 ? Integer.parseInt(String.valueOf(label1.charAt(1))) : Integer.parseInt(String.valueOf(label1.charAt(2)));
                                        if (label1.contains(seatToBook) && (pcount >= passengerCount)) {
                                            seat1.click();
                                            break;
                                        }
                                    }
                                }
                                if (maeGUIObjects.REMOVE_ICONS_AVAILABLE.size() >= segmentsToCheck) {
                                    break Dates;
                                }
                            }
                        }
                        if (maeGUIObjects.REMOVE_ICONS_AVAILABLE.size() >= segmentsToCheck) {
                            break Dates;
                        }

                    }

                }
                maeGUIObjects.CAROUSEL_RIGHT_ARROW.click();
                NextDt.click();
                gl.waitProgress();
            }
        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


    public void toCheckAccountCodeInQuotesSubTab(ExtentTest logInfo, String accountCode) {
        try {
            gl.waitForProfileLoad();
            gl.clickElement(maeGUIObjects.QUOTES_OPTION);
            gl.waitProgress();
            gl.scrollToWebElement(maeGUIObjects.TICKETS_TAB_QUOTES_ACCOUNTCODE);
            String accountCodeFromUI = maeGUIObjects.TICKETS_TAB_QUOTES_ACCOUNTCODE_VALUE.getText();

            if (accountCodeFromUI.contains(accountCode)) {
                logInfo.pass("The Account code is :" + accountCode);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            } else {

                logInfo.fail("The Account code is not present/Account code is not correct");
                Assert.fail("The Account code is not present/Account code is not correct");
            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


    public void selectFlightForSecondSegment(String cabin, ExtentTest logInfo) {
        int segmentsToCheck = 2;
        maeGUIObjects.FLIGHTS_AVAILABLE.get(2).click();
        gl.waitProgress();
        if (cabin.equalsIgnoreCase("Economy")) {
            returnFullEconomy(logInfo, segmentsToCheck);
        } else if (cabin.equalsIgnoreCase("Business")) {
            returnFullBusiness(logInfo, segmentsToCheck);
        } else {
            returnAnySeat(segmentsToCheck);
        }

    }

