    public void enterPrimaryDocumentDetailsForDoubleNationality(ExtentTest logInfo, int i) {

        try {
            logInfo.info(MarkupHelper.createLabel("I enter the Primary Document Details", ExtentColor.PURPLE));

            ArrayList<Passenger> passengers = mPassengers.get(getDriverID());
            gl.clickElement(maeGUIObjects.PRIMARY_DOCUMENT_BUTTON);

            String s = maeGUIObjects.PASSENGER_NAMES_LIST.get(i).getText();
            String[] arr = s.split("/", 2);

            for (int j = 0; j < maeGUIObjects.PASSENGERS_LIST.size(); j++) {
                if (arr[0].equalsIgnoreCase(passengers.get(j).getfName()))  //Checking if the current Passenger from Checkin pax List matches with Fname pax
                {
//                If it matches the details then Enter all other details of Passenger

                    gl.inputText(maeGUIObjects.SURNAME_INPUT, passengers.get(j).getfName());
                    gl.waitForProfileLoad();
                    gl.inputText(maeGUIObjects.GIVEN_NAME_INPUT, passengers.get(j).getlName());
                    gl.waitForProfileLoad();

                    gl.inputText(maeGUIObjects.DATE_OF_BIRTH_INPUT, passengers.get(j).getDOB());
                    gl.waitForProfileLoad();

                    gl.clickElement(maeGUIObjects.GENDER_DROPMENU);
                    if (passengers.get(j).getGender().equalsIgnoreCase("Male")) {
                        gl.clickElement(maeGUIObjects.MALE_DROPMENU);
                        gl.waitProgress();
                    } else {
                        gl.clickElement(maeGUIObjects.FEMALE_DROPMENU);
                        gl.waitProgress();
                    }

                    String docNumber = String.valueOf(10000000 + new Random().nextInt(90000));
                    String docNumber1 = "A"+docNumber;
                    gl.inputText(maeGUIObjects.DOC_NUMBER_INPUT, docNumber1);

                    gl.waitForProfileLoad();
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                    String year = gl.generateYear(2);
                    gl.inputText(maeGUIObjects.EXPIRATION_DATE_INPUT, year);

                    gl.waitForProfileLoad();

                    String code;
                    do {
                        maeGUIObjects.COUNTRY_ISSUANCE_INPUT.click();
                        maeGUIObjects.COUNTRY_ISSUANCE_INPUT.clear();
                        gl.waitProgress();
                        maeGUIObjects.COUNTRY_ISSUANCE_INPUT.click();
                        maeGUIObjects.COUNTRY_ISSUANCE_INPUT.sendKeys("US");
                        gl.waitForProfileLoad();
                        maeGUIObjects.COUNTRY_ISSUANCE_INPUT.sendKeys(Keys.ENTER);
                        gl.waitProgress();
                        code = maeGUIObjects.COUNTRY_ISSUANCE_INPUT.getAttribute("value");
                        System.out.println("Country : " + code);
                    } while ((maeGUIObjects.PASSENGER_COUNTRY_OF_ISSUANCE_ERROR.size() > 0) || (StringUtils.isBlank(code)));

                    do {
                        maeGUIObjects.NATIONALITY_INPUT.click();
                        maeGUIObjects.NATIONALITY_INPUT.clear();
                        gl.waitProgress();
                        maeGUIObjects.NATIONALITY_INPUT.click();
                        maeGUIObjects.NATIONALITY_INPUT.sendKeys("PA");
                        gl.waitForProfileLoad();
                        maeGUIObjects.NATIONALITY_INPUT.sendKeys(Keys.ENTER);
                        gl.waitProgress();
                        code = maeGUIObjects.NATIONALITY_INPUT.getAttribute("value");
                        System.out.println("Country : " + code);
                    } while ((maeGUIObjects.PASSENGER_NATIONALITY_ERROR.size() > 0) || (StringUtils.isBlank(code)));

                    do {
                        maeGUIObjects.COUNTRY_RESIDENCE_INPUT.click();
                        maeGUIObjects.COUNTRY_RESIDENCE_INPUT.clear();
                        maeGUIObjects.COUNTRY_RESIDENCE_INPUT.click();
                        maeGUIObjects.COUNTRY_RESIDENCE_INPUT.sendKeys("US");
                        gl.waitForProfileLoad();
                        maeGUIObjects.COUNTRY_RESIDENCE_INPUT.sendKeys(Keys.ENTER);
                        gl.waitProgress();
                        code = maeGUIObjects.COUNTRY_RESIDENCE_INPUT.getAttribute("value");
                        System.out.println("Country : " + code);
                        logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    } while ((maeGUIObjects.PASSENGER_COUNTRY_OF_RESIDENCE_ERROR.size() > 0) || (StringUtils.isBlank(code)));

                    gl.waitForProfileLoad();
                    String exitDate = gl.plusDaysFromToday(14);
                    gl.inputText(maeGUIObjects.EXIT_DATE_INPUT, exitDate);

                    gl.waitForProfileLoad();
                    gl.inputText(maeGUIObjects.JUSTIFICATION_INPUT, "Justification");

                    logInfo.pass("I enter the Primary Document details for Pax :" + passengers.get(j).getfName() + "/" + passengers.get(j).getlName());
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                    break;
                }
            }

            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            logInfo.pass("I successfully enter the Primary Document Details for Pax: " + s);
        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }

    }

