    public void validateAmountInIcoupon(ExtentTest logInfo, String currency) {
        try {

            maeGUIObjects.COMPENSATION_EMD_PRINT_BUTTON.click();
            gl.waitForProfileLoad();
            waitUntilPageLoad(logInfo);

            List<WebElement> voucherList = maeGUIObjects.PASSENGER_DIGITAL_VOUCHER_LIST;
            for (WebElement voucher : voucherList) {
                gl.waitForProfileLoad();
                voucher.click();
            }
            gl.waitForProfileLoad();
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            gl.waitForProfileLoad();
            gl.waitProgress();
            String xpathAmount = String.format("//div[@class='md-label' and contains(text(),'%s')]", currency);
            List<WebElement> allAmounts = driver.get().findElements(By.xpath(xpathAmount));
            for (int i = 0; i < allAmounts.size(); i++) {
                WebElement amountElement = allAmounts.get(i);
                String fullline = amountElement.getText();
                String[] parts = fullline.split(" ");
                String amount = "";

                for (int k = 0; k < parts.length - 1; k++) {
                    if (parts[k].equals(currency)) {
                        amount = parts[k] + " " + parts[k + 1];
                        System.out.println("Extracted amount: " + amount);
                        break;
                    }
                }

                logInfo.info(MarkupHelper.createLabel("The amount for passenger " + (i + 1) + " is: " + amount, ExtentColor.GREEN));
            }


            maeGUIObjects.DIGITAL_VOUCHER_CANCEL_BUTTON.click();
            gl.waitForProfileLoad();
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

