    public void changeCOSForRequiredConnectingSegment(ExtentTest logInfo, String cos, String segment) {

        try {
            int seg = Integer.parseInt(segment);
            if (seg == 1) {
                gl.waitProgress();
                maeGUIObjects.ORDER_TAB_FIRST_CONNECTING_SEGMENT_CLASS.click();
            } else if (seg == 2) {
                gl.waitProgress();
                maeGUIObjects.ORDER_TAB_SECOND_CONNECTING_SEGMENT_CLASS.click();
            }
            gl.waitProgress();
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            List<WebElement> cosListDropDown = maeGUIObjects.ORDER_TAB_CONNECTING_SEGMENT_CLASS_DROPDOWN;

            for (WebElement listDD : cosListDropDown) {
                gl.waitProgress();
                listDD.click();
                gl.waitProgress();
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                boolean classPresent = false;
                List<WebElement> dropDownValues = maeGUIObjects.ORDER_TAB_FIRST_SEGMENT_CLASS_DROPDOWN_VALUES;

                for (WebElement values : dropDownValues) {
                    if (values.getText().equalsIgnoreCase(cos)) {
                        gl.waitProgress();
                        gl.waitForProfileLoad();
                        values.click();
                        logInfo.pass(cos + " has been selected");
                        classPresent = true;
                        break;
                    }
                }
                if (!classPresent) {
                    Assert.fail(cos + " is not available.");
                }

            }
            gl.waitProgress();
            maeGUIObjects.SAVE_BUTTON.click();
            gl.waitProgress();
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            if (gl.existElement(maeGUIObjects.PRICE_QUOTE_WARNING_DROPDOWNS_1)) {
                maeGUIObjects.PRICE_QUOTE_WARNING_DROPDOWN_1.click();
                gl.waitProgress();
                List<WebElement> messages = maeGUIObjects.WARNING_MESSAGES_1;
                for (int i = 0; i < messages.size(); i++) {
                    String msgText = messages.get(i).getText();
                    if (msgText.equalsIgnoreCase("There was an error while processing the Booking request.") || msgText.contains("CHECK CLASS STATUS/AVAILABILITY FOR THE SEGMENT")) {
                        JavascriptExecutor js = (JavascriptExecutor) getDriver();
                        js.executeScript("arguments[0].style.border='3px solid blue'", messages.get(i));

                        logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                        logInfo.fail("There was an error while processing the Booking request./CHECK CLASS STATUS/AVAILABILITY FOR THE SEGMENT is displaying");
                        Assert.fail("There was an error while processing the Booking request./CHECK CLASS STATUS/AVAILABILITY FOR THE SEGMENT is displaying");
                    }

                }
                gl.waitProgress();
                gl.clickElement(maeGUIObjects.PRICE_QUOTE_WARNING_DROPDOWN_1);
            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            org.junit.Assert.fail("This step failed.. so stopping...");
        }

    }

