    public void selectPassengersAndClickPrintAndClickContinuePrintingButton(ExtentTest logInfo) {
        try {

            Passenger pax = mPassengers.get(getDriverID()).get(0);

            gl.waitProgress();
            gl.clickElement(maeGUIObjects.COMPENSATION_DROP_DOWN);
            gl.waitForProfileLoad();
            gl.clickElement(maeGUIObjects.COMPENSATION_ORDER_ID);
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            gl.clickElement(maeGUIObjects.ISSUE_COMPENSATION_SEARCH_AREA);
            maeGUIObjects.ISSUE_COMPENSATION_SEARCH_AREA.sendKeys(pax.getPnr());
            gl.waitForProfileLoad();

            List<WebElement> passengerList = maeGUIObjects.COMPENSATION_ISSUED_PAX_LIST;
            List<WebElement> pnrList = maeGUIObjects.COMPENSATION_PNR_LIST1;
            List<Passenger> pax1 = mPassengers.get(getDriverID());

            for (Passenger pax2 : pax1) {

                String expectedName = (pax2.getfName() + "/" + pax2.getlName()).replaceAll(" ", "").toLowerCase();
                String expectedPNR = pax2.getPnr().trim();


                for (int j = 0; j < passengerList.size(); j++) {
                    String actualName = passengerList.get(j).getText().replaceAll(" ", "").toLowerCase();
                    String actualPNR = pnrList.get(j).getText().trim();


                    // Optionally use contains() instead of equals() if formatting is inconsistent
                    if (actualName.contains(expectedName) && actualPNR.equalsIgnoreCase(expectedPNR)) {
                        String xpath_SelectPax = "(//md-checkbox[@ng-model='reports.selected'])[" + (j + 1) + "]";
                        WebElement selectPassenger = driver.get().findElement(By.xpath(xpath_SelectPax));
                        selectPassenger.click();
                        gl.waitForProfileLoad();
                        logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Selected Passenger: " + pax2.getFullName());
                        break;
                    }
                }
            }

            maeGUIObjects.COMPENSATION_PRINT_BUTTON.click();
            gl.waitForProfileLoad();
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            gl.clickElement(maeGUIObjects.CONTINUE_PRINTING_IN_COMPENSATION);
            waitUntilPageLoad(logInfo);
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            if (gl.isElementVisible(maeGUIObjects.PRINT_SCCESSFUL_MESSAGE)) {

                JavascriptExecutor js = (JavascriptExecutor) getDriver();
                js.executeScript("arguments[0].style.border='3px solid red'", maeGUIObjects.PRINT_SCCESSFUL_MESSAGE);
                logInfo.pass(MarkupHelper.createLabel("Passenger details Printed successfully after compensation Issued", ExtentColor.GREEN));
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            } else {
                logInfo.fail("Compensation issued not Successfull for the Selected Passenger");
                Assert.fail("Passenger details not printed Successfully");
            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            org.junit.Assert.fail("This step failed.. so stopping...");
        }
    }


