    public void bookFlightOnMonday(String startDate, String returnDate, ExtentTest logInfo) {

        try {

            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String dt = startDate.substring(0, 2);
            int days = Integer.parseInt(dt);

            for (int i = 0; i < 7; i++) {

                LocalDate tomorrow = LocalDate.now().plusDays(days); // 08/10/2025
                int day = tomorrow.getDayOfMonth();  // 8
                String month = tomorrow.getMonth().name();// e.g., AUGUST
                String month1 = month.charAt(0) + month.substring(1).toLowerCase();
                String day1 = tomorrow.getDayOfWeek().name();  //Monday
                String day2 = day1.charAt(0) + day1.substring(1).toLowerCase();
                int year = tomorrow.getYear();

                if (day2.equalsIgnoreCase("Monday")) {
                    String xpath_SearchOptionSelection2 = "//button[@class='md-datepicker-button md-icon-button md-button md-ink-ripple']";
                    WebElement SEARCH_TYPE2 = driver.get().findElement(By.xpath(xpath_SearchOptionSelection2));
                    gl.clickElement(SEARCH_TYPE2);
                    gl.waitForProfileLoad();
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                    String xpath = "//tr//td[@aria-label='" + day2 + " " + month1 + " " + day + " " + year + "']";
                    WebElement dateElement = getDriver().findElement(By.xpath(xpath));
                    gl.waitProgress();
                    dateElement.click();
                    break;

                } else {
                    days++;

                }
            }
            pax.setFirstSegDate(days);

            dt = returnDate.substring(0, 2);
            days = Integer.parseInt(dt);
            int day = days + pax.getFirstSegDate();
            returnDate = gl.plusDaysFromToday(day);

            gl.waitForProfileLoad();
            maeGUIObjects.RETURN_FLIGHT_CHECKBOX.click();
            gl.waitForProfileLoad();
            maeGUIObjects.enterTravelDate2.sendKeys(Keys.chord(Keys.CONTROL + "a" + Keys.BACK_SPACE));
            maeGUIObjects.enterTravelDate2.sendKeys(Keys.BACK_SPACE, returnDate);
            logInfo.pass("I enter Start date: " + startDate + " and return date: " + returnDate + " and search for flights");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }

    }

