    public void storeEmdAndTicketDetailsAndValidatePayment(ExtentTest logInfo) {
        Passenger passenger = mPassengers.get(getDriverID()).get(0);
        try {
            ArrayList<Passenger> pax = mPassengers.get(getDriverID());

            gl.highLightErrorMessages(logInfo, "System Processing Error");

            String expected = "Payment Successful";
            String actual = maeGUIObjects.PAYMENT_SUCCESSFUL.getText();
            Assert.assertEquals(expected, actual);

            logInfo.pass("Validated the message - Payment Successful");
            waitUntilPageLoad(logInfo);
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            List<WebElement> Tickets = driver.get().findElements(By.xpath("//div[contains(@class, 'pax-info-result') and @ng-repeat[contains(., 'paxInfo in passengerResult.passengers')]]   //div[@ng-repeat[contains(., 'Document in paxInfo.PassengerDocument')]]     /div[@ng-switch and contains(@class, 'layout-row')]     [span[@translate='pssgui.ticket' and @ng-switch-when='ETKT']]     /span[@class='ng-binding']"));
            List<WebElement> EMD = driver.get().findElements(By.xpath("//div[contains(@class,'pax-info-result')]//div[@ng-repeat][div/span[@translate='pssgui.emd']]/div/span[@class='ng-binding']"));
            JavascriptExecutor js = (JavascriptExecutor) getDriver();

            List<WebElement> paxlist = getDriver().findElements(By.xpath("//md-checkbox[@ng-model='paxInfo.isChecked']//following-sibling::div[@class='pssgui-design-sub-heading-6 word-break ng-binding flex']"));
            for (int i = 0; i < paxlist.size(); i++) {

                if (gl.existElement(Tickets)) {

                    String name = paxlist.get(i).getText();
                    for (Passenger value : pax) {
                        String fname = value.getfName();
                        String lname = value.getlName();
                        String finalName = fname + ", " + lname;
                        if (name.equalsIgnoreCase(finalName)) {

                            String type = value.getPaxType();
                            if (type.equalsIgnoreCase("ADT") || type.equalsIgnoreCase("FQTV")) {

                                String ticketNum = Tickets.get(i).getText();
                                pax.get(i).setUpdatedTicketNumber(ticketNum);
                                System.out.println(pax.get(i).getUpdatedTicketNumber());
                                gl.scrollToWebElement(Tickets.get(i));
                                js.executeScript("arguments[0].style.border='3px solid red'", Tickets.get(i));
                                pax.get(i).setADTTicketNumber(ticketNum);
                                logInfo.info("Ticket Number for Adult : " + ticketNum);
                                break;
                            } else if (type.equalsIgnoreCase("CHD")) {

                                String ticketNum = Tickets.get(i).getText();
                                pax.get(i).setUpdatedTicketNumber(ticketNum);
                                System.out.println(pax.get(i).getUpdatedTicketNumber());
                                gl.scrollToWebElement(Tickets.get(i));
                                js.executeScript("arguments[0].style.border='3px solid red'", Tickets.get(i));
                                pax.get(i).setCHDTicketNumber(ticketNum);
                                logInfo.info("Ticket Number for Child : " + ticketNum);
                                break;
                            } else if (type.equalsIgnoreCase("INF")) {

                                String ticketNum = Tickets.get(i).getText();
                                pax.get(i).setUpdatedTicketNumber(ticketNum);
                                System.out.println(pax.get(i).getUpdatedTicketNumber());
                                gl.scrollToWebElement(Tickets.get(i));
                                js.executeScript("arguments[0].style.border='3px solid red'", Tickets.get(i));
                                pax.get(i).setINFTicketNumber(ticketNum);
                                logInfo.info("Ticket Number for INF : " + ticketNum);
                                break;
                            } else if (type.equalsIgnoreCase("INS")) {

                                String ticketNum = Tickets.get(i).getText();
                                pax.get(i).setUpdatedTicketNumber(ticketNum);
                                System.out.println(pax.get(i).getUpdatedTicketNumber());
                                gl.scrollToWebElement(Tickets.get(i));
                                js.executeScript("arguments[0].style.border='3px solid red'", Tickets.get(i));
                                pax.get(i).setINSTicketNumber(ticketNum);
                                logInfo.info("Ticket Number for INS : " + ticketNum);
                                break;
                            }
                        }

                    }
                }


                if (gl.existElement(EMD)) {
                    pax.get(i).setUpdatedEMDNumber(EMD.get(i).getText());
                    System.out.println(pax.get(i).getUpdatedEMDNumber());
                    gl.waitProgress();
                    gl.waitForProfileLoad();
                    js.executeScript("arguments[0].style.border='3px solid red'", EMD.get(i));
                }
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            }

            maeGUIObjects.PaymentDoneButton.click();
            gl.waitProgress();
            gl.waitForProfileLoad();
            logInfo.pass("Order Number Generated: " + passenger.getPnr());
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            DateTimeFormatter formatter = DateTimeFormatter.ofPattern("dd-MMM-yyyy");
            LocalDate targetDate;

            String systemDate = maeGUIObjects.SYSYTEM_DATE.getText().substring(0,11);
            targetDate = LocalDate.parse(systemDate, formatter);
            LocalDate today = LocalDate.now();
            long daysBetween = ChronoUnit.DAYS.between(today, targetDate);

                passenger.setSystemDate(0, (int) daysBetween);

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }

    }


