    public void comparison(ExtentTest logInfo, List<String> expectedTaxes, List<String> actualTaxes) {
        try {
            List<String> normalizedExpected = new ArrayList<>();
            for (String expected : expectedTaxes) {
                String[] parts = expected.trim().split("\\s+");
                if (parts.length >= 3) {
                    // Remove the currency (last part)
                    normalizedExpected.add(parts[0] + " " + parts[1]);
                } else {
                    // If already without currency
                    normalizedExpected.add(expected.trim());
                }
            }

            List<String> normalizedActual = new ArrayList<>();
            for (String actual : actualTaxes) {
                normalizedActual.add(actual.trim());
            }

            // Sort both lists for comparison
            Collections.sort(normalizedExpected);
            Collections.sort(normalizedActual);

            // Log the sorted lists
            logInfo.info("Sorted Expected Taxes: " + normalizedExpected);
            logInfo.info("Sorted Actual Taxes  : " + normalizedActual);

            // Compare sizes
            if (normalizedExpected.size() == normalizedActual.size()) {
                logInfo.info("Both the Expected and Actual Taxes have the same size");

                boolean allMatch = true;
                for (int i = 0; i < normalizedExpected.size(); i++) {
                    if (!normalizedExpected.get(i).equals(normalizedActual.get(i))) {
                        allMatch = false;
                        break;
                    }
                }

                if (allMatch) {
                    logInfo.pass("Both the Tax values matched.\nExpected: " + normalizedExpected + "\nActual  : " + normalizedActual);
                } else {
                    logInfo.fail("Both the Tax values doesn't matched.\nExpected: " + normalizedExpected + "\nActual  : " + normalizedActual);
                    Assert.fail("Both the Tax values doesn't matched");
                }

            } else {
                logInfo.fail("Tax list sizes do not match.\nExpected size: " + normalizedExpected.size() + "\nActual size  : " + normalizedActual.size());
                Assert.fail("Tax list sizes do not match.");
            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

