    public void clickAddBaggageIconForSpcificPax(ExtentTest logInfo, String paxType) {
        try {
            gl.waitForProfileLoad();
            ArrayList<Passenger> pax = mPassengers.get(getDriverID());
            List<WebElement> pNameList = maeGUIObjects.PASSENGER_NAME_CHECKIN_PAGE;
            for (int i = 0; i < pNameList.size(); i++) {

                String xpath_PaxType = "(//md-select[@ng-model='passengerData.PassengerTypeCode'])[" + (i + 1) + "]";
                WebElement passengerType = driver.get().findElement(By.xpath(xpath_PaxType));
                String PType = passengerType.getText();

                String xpath_FFNumber = "(//input[@ng-model='fqtvDetail.MembershipID'])[" + (i + 1) + "]";
                WebElement FFNumber = driver.get().findElement(By.xpath(xpath_FFNumber));
                String ffNumber = FFNumber.getAttribute("value");

                if (paxType.equalsIgnoreCase("FQTV")) {
                    if (PType.equalsIgnoreCase("Adult") && !ffNumber.isEmpty()) {

                        String xpath = "(//i[@class='icon-baggage'])[" + (i + 1) + "]";
                        WebElement bagIcon = driver.get().findElement(By.xpath(xpath));
                        gl.scrollTo(bagIcon);
                        //bagIcon.click();
                        gl.clickElement(bagIcon);
                        break;
                    }
                } else if (paxType.equalsIgnoreCase("Adult")) {

                    if (PType.equalsIgnoreCase("Adult") && ffNumber.isEmpty()) {

                        String xpath = "(//i[@class='icon-baggage'])[" + (i + 1) + "]";
                        WebElement bagIcon = driver.get().findElement(By.xpath(xpath));
                        gl.scrollTo(bagIcon);
                        //bagIcon.click();
                        gl.clickElement(bagIcon);
                        break;
                    }
                } else if (paxType.equalsIgnoreCase("Child")) {

                    if (PType.equalsIgnoreCase("Child") && ffNumber.isEmpty()) {

                        String xpath = "(//i[@class='icon-baggage'])[" + (i + 1) + "]";
                        WebElement bagIcon = driver.get().findElement(By.xpath(xpath));
                        gl.scrollTo(bagIcon);
                        //bagIcon.click();
                        gl.clickElement(bagIcon);
                        break;
                    }
                }
            }

            gl.waitForProfileLoad();
            logInfo.pass("I click on Baggage icon for specific pax");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


