    public void addASSRWithOptionInGUI(ExtentTest logInfo, String SSR, String ssrDescription) {
        try {
            logInfo.info(MarkupHelper.createLabel("I click on the services tab", ExtentColor.PURPLE));

            gl.clickElement(maeGUIObjects.SERVICES_TAB);
            gl.waitProgress();
            gl.waitForProfileLoad();
            logInfo.pass("I click on the services tab");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            logInfo.info(MarkupHelper.createLabel("I select all services and segments checkbox", ExtentColor.PURPLE));

            if (maeGUIObjects.ALL_SEGMENTS_CHECKBOX_UNCHECKED.size() > 0)
                maeGUIObjects.ALL_SEGMENTS_CHECKBOX.click();

            if (maeGUIObjects.ALL_PASSENGERS_CHECKBOX_UNCHECKED.size() > 0)
                maeGUIObjects.ALL_PASSENGERS_CHECKBOX.click();
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            logInfo.info(MarkupHelper.createLabel("I enter the input services as " + SSR, ExtentColor.PURPLE));
            maeGUIObjects.INPUT_SERVICES.sendKeys(SSR);
            gl.waitForProfileLoad();
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            if (SSR.equalsIgnoreCase("PETC")) {
                if (ssrDescription.equalsIgnoreCase("PET IN CABIN - 0BT")) {
                    WebElement SSRENTER = driver.get().findElement(By.xpath("//li[contains(@class, 'md-autocomplete-suggestion') and contains(., 'PET IN CABIN') and contains(., '0BT')]"));
                    gl.clickElement(SSRENTER);
                    gl.waitForProfileLoad();
                } else if (ssrDescription.equalsIgnoreCase("Pet in cabin - ")) {
                    WebElement SSRENTER = driver.get().findElement(By.xpath("//li[contains(@class, 'md-autocomplete-suggestion') and contains(., 'Pet in cabin') and contains(., '-')]"));
                    gl.clickElement(SSRENTER);
                    gl.waitForProfileLoad();
                }
            }
            maeGUIObjects.INPUT_SERVICES.sendKeys(Keys.ENTER);
            gl.waitProgress();
            logInfo.pass("I enter the input services as " + SSR);
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            gl.scrollToWebElement(maeGUIObjects.SERVICES_SEARCH_ICON);
            gl.clickElement(maeGUIObjects.SERVICES_SEARCH_ICON);
            gl.waitProgress();
            gl.waitForProfileLoad();

            logInfo.info(MarkupHelper.createLabel("I enter the services explanation." + SSR, ExtentColor.PURPLE));

            for (WebElement webElement : maeGUIObjects.SERVICES_EXPLANATIONS) {
                if (webElement.isEnabled()) {
                    if (SSR.equalsIgnoreCase("BULK"))
                        gl.inputText(webElement, " 20KG FREETEXT");
                    else
                        gl.inputText(webElement, SSR);
                }
            }

            logInfo.pass("I enter the services explanation.");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            gl.clickButton(maeGUIObjects.ADD_TO_ORDER);
            gl.waitProgress();
            gl.waitForProfileLoad();
            List<WebElement> checkOutButton = driver.get().findElements(By.xpath("//button[contains(@class, 'md-button') and contains(., 'Check Out')]"));
            if (!gl.existElement(checkOutButton)) {
                String ssrPath = String.format("//div[@class='ng-binding ng-scope' and contains(text(),'%s')]", SSR);
                WebElement SSR_ELEMENT = driver.get().findElement(By.xpath(ssrPath));
                gl.scrollToWebElement(SSR_ELEMENT);
                gl.waitProgress();
                gl.waitForProfileLoad();
            }
            logInfo.pass("I click on add to order button");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

