    public void changeDateOfTravelForThirdSeg(ExtentTest logInfo, String newDate) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            Pattern pattern = Pattern.compile("\\b\\d{2,3}\\b");
            Matcher matcher = pattern.matcher(newDate);
            String timeCode = null;
            if (matcher.find()) {
                timeCode = matcher.group();
                System.out.println("Extracted time: " + timeCode);
            } else {
                System.out.println("No matching time found.");
            }
            String dt = timeCode;
            int days = Integer.parseInt(dt);
            int day = days + pax.getSecondSegDate();
            newDate = gl.plusDaysFromToday(day);
            System.out.println("New date: " + newDate);

            gl.clickElement(maeGUIObjects.SEGMENT_3_DATE_OF_TRAVEL);
            gl.waitProgress();
            gl.waitForProfileLoad();
            gl.clickElement(maeGUIObjects.SEGMENT_3_DATE_FIELD);
            gl.waitProgress();
            gl.waitForProfileLoad();
            maeGUIObjects.SEGMENT_3_DATE_FIELD.sendKeys(Keys.chord(Keys.CONTROL + "a"));
            gl.waitProgress();
            gl.waitForProfileLoad();
            maeGUIObjects.SEGMENT_3_DATE_FIELD.sendKeys(Keys.BACK_SPACE);
            gl.waitProgress();
            gl.waitForProfileLoad();
            maeGUIObjects.SEGMENT_3_DATE_FIELD.sendKeys(newDate);
            gl.waitProgress();
            gl.waitForProfileLoad();
            maeGUIObjects.SAVE_BUTTON.click();
            gl.waitProgress();
            gl.waitForProfileLoad();

            while (gl.existElement(maeGUIObjects.ORDER_TAB_UNABLE_TO_BOOKREQUESTEDFLIGHT) || gl.existElement(maeGUIObjects.ORDER_TAB_SELL_ITINERARY_PROCESS_FAILED_ERROR_MESSAGE)) {
                day++;
                newDate = gl.plusDaysFromToday(day);
                System.out.println("New date: " + newDate);

                gl.clickElement(maeGUIObjects.SEGMENT_3_DATE_OF_TRAVEL);
                gl.waitProgress();
                gl.waitForProfileLoad();
                gl.clickElement(maeGUIObjects.SEGMENT_3_DATE_FIELD);
                gl.waitProgress();
                gl.waitForProfileLoad();
                maeGUIObjects.SEGMENT_3_DATE_FIELD.sendKeys(Keys.chord(Keys.CONTROL + "a"));
                gl.waitProgress();
                gl.waitForProfileLoad();
                maeGUIObjects.SEGMENT_3_DATE_FIELD.sendKeys(Keys.BACK_SPACE);
                gl.waitProgress();
                gl.waitForProfileLoad();
                maeGUIObjects.SEGMENT_3_DATE_FIELD.sendKeys(newDate);
                gl.waitProgress();
                gl.waitForProfileLoad();
                gl.waitProgress();
                maeGUIObjects.SAVE_BUTTON.click();
                gl.waitProgress();
                gl.waitProgress();
                gl.waitForProfileLoad();
            }
            pax.setThirdSegDate(day);
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            logInfo.pass("I change the date of travel for the second segment");

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

