    private boolean processEMDEntries(List<Passenger> paxList, ExtentTest logInfo) throws Exception {
        List<WebElement> reportEmd = maeGUIObjects.SALE_REPORT_EMD_NUMBERS;

        for (int j = 0; j < reportEmd.size(); j++) {
            String value = reportEmd.get(j).getText();

            for (Passenger pax : paxList) {
                String exchangedEMD = pax.getUpdatedEMDNumber();
                String exchangedTicket = pax.getUpdatedTicketNumber();

                if (value.equals(exchangedEMD) || value.equals(exchangedTicket)) {
                    // Expand toggle
                    String arrowXpath = "(//i[@class='toggle-arrow icon-forward'])[" + (j + 1) + "]";
                    WebElement arrow = driver.get().findElement(By.xpath(arrowXpath));
                    gl.scrollTo(arrow);
                    arrow.click();
                    gl.waitForProfileLoad();

                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Expanded EMD row");

                    // SSR Elements
                    List<WebElement> ssrs = driver.get().findElements(By.xpath(
                            "//div[contains(@class, 'content-expand')]//div[@layout='row' and contains(@class, 'layout-row') and descendant::div[contains(@class, 'pssgui-design-text-general') and contains(., 'Coupon')]]"
                    ));

                    if (!ssrs.isEmpty()) {
                        for (WebElement ssr : ssrs) {
                            gl.scrollToWebElement(ssr);
                            ((JavascriptExecutor) getDriver()).executeScript("arguments[0].style.cssText = 'border: 3px solid red; background-color: yellow;'", ssr);
                            Thread.sleep(1000);
                            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "SSR Highlighted");
                            logInfo.info(MarkupHelper.createLabel("SSR available in EMD: " + ssr.getText(), ExtentColor.GREEN));
                        }
                    }

                    // Tax Icon
                    String taxXpath = "(//i[@class='pssgui-design-layout-04 icon-tax icon-small'])[" + (j + 1) + "]";
                    WebElement tax = driver.get().findElement(By.xpath(taxXpath));
                    gl.scrollTo(tax);
                    tax.click();
                    gl.waitForProfileLoad();
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "EMD Tax Clicked");

                    // Close popup
//                if (gl.existElement(maeGUIObjects.EMD_TAX_POP_UP)) {
                    gl.clickElement(maeGUIObjects.EMD_TAX_POP_UP);
                    gl.waitProgress();
                    gl.waitForProfileLoad();
//                }

                    return true; // Exit once matched
                }
            }
        }

        return false; // No match found
    }

    public void validateSSREMD(ExtentTest logInfo) {
        try {
            List<Passenger> paxList = mPassengers.get(getDriverID());
            if (paxList == null || paxList.isEmpty()) return;

            Passenger firstPax = paxList.get(0);

            gl.waitForProfileLoad();

            if (gl.existElement(maeGUIObjects.PAGE_NUMBER)) {
                // Handle pagination
                WebElement pageNo = maeGUIObjects.PAGE_NUMBERS;
                int pageSize = Integer.parseInt(pageNo.getText().split("/")[1].trim());

                gl.clickElement(maeGUIObjects.DOCUMENT_TYPE_DROPDOWN);
                gl.waitForProfileLoad();
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                gl.clickElement(maeGUIObjects.OPTION_EMD);
                gl.waitProgress();
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                for (int page = 0; page < pageSize; page++) {
                    if (processEMDEntries(paxList, logInfo)) break;

                    List<WebElement> nextPageElements = driver.get().findElements(By.xpath("//div[@ng-click='reportPaging.nextPage()']"));
                    if (gl.existElement(nextPageElements)) {
                        gl.clickElement(maeGUIObjects.NEXT_PAGE_ARROW);
                        gl.waitForProfileLoad();
                    }
                }

            } else {
                // No pagination case
                gl.waitProgress();
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                processEMDEntries(paxList, logInfo);
            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

