    public void setEmailFQTV(ExtentTest logInfo) {
        try {

            List<WebElement> NEXTBUTTON = driver.get().findElements(By.xpath("//button[contains(@ng-click, 'foid') and normalize-space(text())='Next']"));
            if (gl.existElement(NEXTBUTTON)) {
                gl.scrollToWebElement(maeGUIObjects.FOID_NEXT_BUTTON);
                gl.clickButton(maeGUIObjects.FOID_NEXT_BUTTON);
                gl.waitProgress();
                gl.waitForProfileLoad();
            }


            WebDriverWait wait = new WebDriverWait(getDriver(), Duration.ofSeconds(10));

// Locate all email input fields inside the recipients container
            List<WebElement> emailInputs = driver.get().findElements(By.cssSelector("input[type='text'][ng-model*='recipient.ToAddr']"));

// Loop through each email input
            for (int i = 0; i < emailInputs.size(); i++) {
                WebElement emailInput = emailInputs.get(i);

                String Email = emailInput.getAttribute("value");
                System.out.println("Email " + i + ": " + Email);

                if (Email != null && !Email.trim().isEmpty()) {
                    System.out.println("Email is not empty, selecting language for recipient " + i);

                    // The language dropdown seems to be the next sibling in the structure
                    // We'll find all language dropdowns and pick the matching index
                    List<WebElement> languageDropdowns = driver.get().findElements(By.cssSelector("md-select[id^='select_']"));
                    WebElement languageDropdown = languageDropdowns.get(i);

                    wait.until(ExpectedConditions.elementToBeClickable(languageDropdown));
                    languageDropdown.click();
                    gl.waitProgress();
                    gl.waitForProfileLoad();
                    // Wait for dropdown options to appear
                    WebElement languageEnglish = driver.get().findElement(By.xpath("(//md-select-menu[contains(@role, 'presentation') and contains(@class, '_md')]/md-content[contains(@role, 'listbox') and contains(@class, '_md')]/md-option[.//span[contains(text(), 'English')]])[2]"));
                    gl.clickElement(languageEnglish);
                    gl.waitProgress();
                    gl.waitForProfileLoad();
                    System.out.println("Selected English language for recipient " + i);
                } else {
                    String email = maeGUIObjects.INPUT_RECIPIENT_EMAIL.getAttribute("value");

                    if (StringUtils.isEmpty(email) || !email.equalsIgnoreCase("testone@testone.com")) {
                        email = "testone@testone.com";

                        maeGUIObjects.INPUT_RECIPIENT_EMAIL.clear();
                        maeGUIObjects.INPUT_RECIPIENT_EMAIL.sendKeys(email);
                        gl.waitForProfileLoad();
                    }
                    System.out.println("Email is empty for recipient " + i + ", skipping language selection.");
                    maeGUIObjects.EmailRecipient_dropDown.click();
                    gl.waitForProfileLoad();
                    maeGUIObjects.EmailLanguageSelect.click();
                    gl.waitForProfileLoad();
                    logInfo.pass("I enter the details in the email recipients page");
                }
            }

            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            maeGUIObjects.EmailButton.click();
            gl.waitProgress();
            wait = new WebDriverWait(getDriver(), Duration.ofSeconds(120));
            wait.until(ExpectedConditions.invisibilityOfElementLocated(By.xpath("//div[@ng-repeat='(key, val) in spinnerMessage.pssguiSpinnerMessageUtil.loadingMessage']")));

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

