    public void payByVoluntaryReissueEMD(ExtentTest logInfo) throws IOException {
        try {
            logInfo.info(MarkupHelper.createLabel("I make the payment through EMD", ExtentColor.PURPLE));

            gl.clickWebElement(maeGUIObjects.PAYMENT_TYPE_OF_PAYMENT.get(maeGUIObjects.PAYMENT_TYPE_OF_PAYMENT.size() - 1));
            gl.clickWebElement(maeGUIObjects.PAYMENT_WITH_MISC_OPTION.get(maeGUIObjects.PAYMENT_WITH_MISC_OPTION.size() - 1));
            gl.waitForProfileLoad();

            gl.clickWebElement(maeGUIObjects.PAYMENT_SUB_TYPE.get(maeGUIObjects.PAYMENT_SUB_TYPE.size() - 1));
            gl.waitForProfileLoad();

            gl.clickWebElement(maeGUIObjects.PAYMENT_WITH_EMD.get(maeGUIObjects.PAYMENT_WITH_EMD.size() - 1));
            gl.waitForProfileLoad();

            gl.scrollTo(maeGUIObjects.EMD_NUMBER.get(maeGUIObjects.EMD_NUMBER.size() - 1));
            maeGUIObjects.EMD_NUMBER.get(maeGUIObjects.EMD_NUMBER.size() - 1).clear();
//            gl.inputText(maeGUIObjects.EMD_NUMBER.get(maeGUIObjects.EMD_NUMBER.size() - 1), mEmd.get(getDriverID()));
            gl.inputText(maeGUIObjects.EMD_NUMBER.get(maeGUIObjects.EMD_NUMBER.size() - 1), mPassengers.get(getDriverID()).get(0).getUpdatedEMDNumber());
            gl.clickWebElement(maeGUIObjects.EMD_CHECK);
            gl.waitProgress();
            gl.waitForProfileLoad();
            logInfo.pass("I make the payment through EMD");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            gl.clickWebElement(maeGUIObjects.Confirm_EMD);
            gl.waitProgress();
            gl.waitForProfileLoad();
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            if (gl.existElement(maeGUIObjects.ADD_ANOTHER_PAYMENT_BUTTON1)) {
                gl.clickButton(maeGUIObjects.ADD_ANOTHER_PAYMENT_BUTTON);
                gl.waitForProfileLoad();

            } else {
                gl.waitForProfileLoad();
                maeGUIObjects.PAYMENT_PAY_BUTTON.click();
                gl.waitForElementAfterReload(getDriver(), maeGUIObjects.CLOSE_ICON, PAGE_LOAD_TIMEOUT);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

