    public void enterSecurityDocumentDetailsWithAllDetails(ExtentTest logInfo) {

        try {

            for (WebElement Orderno : maeGUIObjects.ORDERS_LIST) {
                int i = 0;
                for (WebElement passenger : maeGUIObjects.PASSENGERS_LIST) {
                    gl.waitForProfileLoad();
                    passenger.click();
                    enterPrimaryDocumentDetailsForDoubleNationality(logInfo, i);
                    enterSecondaryDocument(logInfo, i);
                    enterDestinationAddress(logInfo, i);

                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                    if (gl.existElement(maeGUIObjects.NEXT_BUTTON_CHECKIN)) {
                        gl.clickElement(maeGUIObjects.NEXT_BUTTON1_CHECKIN);
                        gl.waitProgress();
                        gl.waitForProfileLoad();
                    } else {
                        submitCheckin();

                    }

                    if (gl.existElement(maeGUIObjects.ADC_OK_BUTTONS)) {

                        logInfo.info(MarkupHelper.createLabel("Page contains ADC Conditional OK & ADC OK button exists", ExtentColor.PURPLE));
                        logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                        maeGUIObjects.ADC_OK_BUTTON.click();
                        WebDriverWait wait = new WebDriverWait(getDriver(), Duration.ofSeconds(120));  // 10 seconds timeout
                        wait.until(ExpectedConditions.invisibilityOfElementLocated(By.xpath("//div[@translate='pssgui.adc.response']")));
                        logInfo.pass(MarkupHelper.createLabel("I click on OK Button", ExtentColor.GREEN));
                    } else if (gl.existElement(maeGUIObjects.ADC_NOT_OK_TEXT)) {


                        logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                        gl.clickElement(maeGUIObjects.CLICK_ADC_BYPASS_CHECK_BOX);
                        gl.waitProgress();
                        logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                        gl.clickElement(maeGUIObjects.ADC_BYPASS_OK_BUTTON);
                        gl.waitProgress();
                        gl.waitForProfileLoad();
                        gl.waitForProfileLoad();
                        logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                        submitCheckin();
                        gl.waitProgress();
                        gl.waitForProfileLoad();
                        String apis_Expected = "ADC Bypassed";
                        String apis_Actual = maeGUIObjects.ADC_BYPASSED.getText();
                        Assert.assertTrue(apis_Actual.contains(apis_Expected));
                    }
                    i++;

                }//end of passenger loop

            }//end of orderId loop

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            org.junit.Assert.fail("This step failed.. so stopping...");
        }

    }


    public void enterDestinationAddress(ExtentTest logInfo, int i) {
        try {
            logInfo.info(MarkupHelper.createLabel("I enter the destination address Details", ExtentColor.PURPLE));

            ArrayList<Passenger> passengers = mPassengers.get(getDriverID());
            gl.clickElement(maeGUIObjects.DESTINATION_ADDRESS_BUTTON);

            String s = maeGUIObjects.PASSENGER_NAMES_LIST.get(i).getText();
            String[] arr = s.split("/", 2);

            for (int j = 0; j < maeGUIObjects.PASSENGERS_LIST.size(); j++) {
                if (arr[0].equalsIgnoreCase(passengers.get(j).getfName()))  //Checking if the current Passenger from Checkin pax List matches with Fname pax
                {
//                If it matches the details then Enter all other details of Passenger


                    String code;
                    do {
                        maeGUIObjects.STREET_ADDRESS_INPUT.click();
                        maeGUIObjects.STREET_ADDRESS_INPUT.clear();
                        maeGUIObjects.STREET_ADDRESS_INPUT.click();
                        maeGUIObjects.STREET_ADDRESS_INPUT.sendKeys("800");
                        gl.waitForProfileLoad();
                        maeGUIObjects.STREET_ADDRESS_INPUT.sendKeys(Keys.ENTER);
                        gl.waitProgress();
                        code = maeGUIObjects.STREET_ADDRESS_INPUT.getAttribute("value");
                        System.out.println("street address : " + code);
                    } while ((maeGUIObjects.PASSENGER_STREET_ADDRESS_ERROR.size() > 0) || (StringUtils.isBlank(code)));


                    maeGUIObjects.INPUT_CITY.click();
                    maeGUIObjects.INPUT_CITY.clear();
                    maeGUIObjects.INPUT_CITY.click();
                    maeGUIObjects.INPUT_CITY.sendKeys("PTY");
                    gl.waitForProfileLoad();
                    maeGUIObjects.INPUT_CITY.sendKeys(Keys.ENTER);
                    gl.waitProgress();

                    logInfo.pass("I enter the destination address details for Pax :" + passengers.get(j).getfName() + "/" + passengers.get(j).getlName());
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                    break;
                }
            }


            gl.waitProgress();
            gl.clickElement(maeGUIObjects.PRIMARY_DOCUMENT_BUTTON);
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            logInfo.pass("I successfully enter the destination address Details for Pax: " + s);
        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            org.junit.Assert.fail("This step failed.. so stopping...");
        }

    }


