    public void passengerCheckInAfterAddingBaggage(ExtentTest logInfo) {
        try {
            int x = 0;

            if (gl.isElementVisible(maeGUIObjects.PRINTER_ACCEPT_BUTTON)) {
                maeGUIObjects.PRINTER_ACCEPT_BUTTON.click();
                gl.waitForProfileLoad();
                gl.waitForProfileLoad();
            }

            do {
                maeGUIObjects.CHECKIN_BUTTON.click();

                WebDriverWait wait = new WebDriverWait(getDriver(), Duration.ofSeconds(120));
                wait.until(ExpectedConditions.invisibilityOfElementLocated(By.xpath("//div[@ng-repeat='(key, val) in spinnerMessage.pssguiSpinnerMessageUtil.loadingMessage']")));

                if (x++ >= 5)
                    break;

                if (gl.existElement(maeGUIObjects.FLIGHT_NO_OPEN_ERROR_MSG)) {
                    assignShipmentNumberToFlightInGUI(0, logInfo);
                }

            } while (!gl.isEnabledNew(maeGUIObjects.RETURN_TO_CHECKIN_BUTTON) && !maeGUIObjects.RETURN_TO_CHECKIN_BUTTON.isDisplayed());

            gl.waitForProfileLoad();
            Passenger pax = mPassengers.get(getDriverID()).get(0);

            int totalBags = pax.getTotalBags();

            WebElement bagCountElement = getDriver().findElement(By.xpath("//span[contains(@class, 'icon-value') and contains(@class, 'ng-binding')]"));

            String bagCountText = bagCountElement.getText().trim();
            int displayedBagCount = Integer.parseInt(bagCountText);

            System.out.println("Expected Bag Count: " + totalBags);
            System.out.println("Displayed Bag Count: " + displayedBagCount);
            if (totalBags == displayedBagCount) {

                JavascriptExecutor js = (JavascriptExecutor) getDriver();
                js.executeScript("arguments[0].style.border = '3px solid green'; arguments[0].style.backgroundColor = '#d4edda';", bagCountElement);

                System.out.println("Bag count matches as expected.");
            } else {
                Assert.fail("Bag count mismatch! Expected: " + totalBags + ", but found: " + displayedBagCount);
            }
            gl.waitForProfileLoad();

            if (gl.isElementVisible(maeGUIObjects.PRINTER_ACCEPT_BUTTON)) {
                maeGUIObjects.PRINTER_ACCEPT_BUTTON.click();
                gl.waitForProfileLoad();
                gl.waitForProfileLoad();
            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


