    public void assignShipmentNumberToFlightInGUIAfterReissue(int index, ExtentTest logInfo) {

        sharesCancelFlag = 0;
        Passenger pax = mPassengers.get(getDriverID()).get(0);

        String origin = pax.getSegmentOriginCity(index);
        String flightNumber = pax.getSegmentFlight(index);
        LocalDateTime departureDate = DateUtil.formatToLocalDateTime(gl.plusDaysFromTodayNew(pax.getConnectingSegmentDate(index)), "10:10");
        System.out.println("Departure Date in Local Date Time format: " + departureDate);

        try {
            logInfo.info(MarkupHelper.createLabel("Click on tools option", ExtentColor.PURPLE));

            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            gl.clickButton(maeGUIObjects.TOOL_MENU);
            gl.waitForProfileLoad();
            logInfo.pass("Click on tools option");

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }

        try {
            logInfo.info(MarkupHelper.createLabel("Click on shares option", ExtentColor.PURPLE));

            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            gl.clickButton(maeGUIObjects.SHARES_OPTION);
            gl.waitProgress();
            gl.waitForProfileLoad();
            logInfo.pass("Click on shares option");

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }


        String command = commandCheckShipmentAssigned(flightNumber,
                departureDate.toLocalDate(), origin);

        try {
            logInfo.info(MarkupHelper.createLabel("Enter Assigned shipment in text area", ExtentColor.PURPLE));

            maeGUIObjects.COMMAND_TEXTAREA.sendKeys(command);

            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            if (maeGUIObjects.SHARES_SUBMIT_BUTTON.size() > 1) {
                gl.clickButton(maeGUIObjects.SHARES_SUBMIT_BUTTON.get(1));
            } else {
                gl.clickButton(maeGUIObjects.SHARES_SUBMIT_BUTTON.get(0));
            }
            gl.waitProgress();
            gl.waitForProfileLoad();

            logInfo.pass("Enter Assigned shipment in text area and click on Submit");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }


        if (gl.existElement(maeGUIObjects.SHIP_NOT_ASSIGNED_MSG)) {
            String departureDateFormatted = DateUtil.formatDateToSharesDateFormat(departureDate.toLocalDate());

            String flightEquipmentLinePath = SHIPMENT_LINE_MSG.replace(FLIGHT_NBR, flightNumber);
            flightEquipmentLinePath = flightEquipmentLinePath.replace(ORIGIN, origin);
            flightEquipmentLinePath = flightEquipmentLinePath.replace(DEPARTURE_DATE, departureDateFormatted);
            String flightEquipmentInfo = findElementXpath(flightEquipmentLinePath, getDriver()).getText();

            flightEquipmentInfo = flightEquipmentInfo.replaceAll("\\s+", " ").trim();
            String[] elements = flightEquipmentInfo.split(" ");
            String equipmentNumber = elements[1].trim();

            command = commandObtainShipmentNumbersAvailable(equipmentNumber);

            try {
                logInfo.info(MarkupHelper.createLabel("Enter shipment numbers in text area", ExtentColor.PURPLE));

                maeGUIObjects.COMMAND_TEXTAREA.sendKeys(command);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                if (maeGUIObjects.SHARES_SUBMIT_BUTTON.size() > 1) {
                    gl.clickButton(maeGUIObjects.SHARES_SUBMIT_BUTTON.get(1));
                } else {
                    gl.clickButton(maeGUIObjects.SHARES_SUBMIT_BUTTON.get(0));
                }

                gl.waitProgress();
                gl.waitForProfileLoad();

                logInfo.pass("Enter shipment numbers in text area and click Submit");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            } catch (AssertionError | Exception e) {

                ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
                Assert.fail("This step failed.. so stopping...");
            }


            String shipmentNumberInfoPath = EQUIPMENT_NUMBERS_DATA_MSG.replace(EQUIPMENT_DATA, equipmentNumber);
            String shipmentNumbersLineInfo = findElementXpath(shipmentNumberInfoPath, getDriver()).getText();

            shipmentNumbersLineInfo = shipmentNumbersLineInfo.replaceAll("\\s+", " ");
            String[] shipmentsElements = shipmentNumbersLineInfo.split(" ");
            String codeToAssign = shipmentsElements[shipmentsElements.length - 1];

            command = commandAssignShipmentNumberToFlight(departureDate.toLocalDate(),
                    flightNumber, origin, codeToAssign);

            try {
                logInfo.info(MarkupHelper.createLabel("Assign shipment number to flight", ExtentColor.PURPLE));

                maeGUIObjects.COMMAND_TEXTAREA.sendKeys(command);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                if (maeGUIObjects.SHARES_SUBMIT_BUTTON.size() > 1) {
                    gl.clickButton(maeGUIObjects.SHARES_SUBMIT_BUTTON.get(1));
                } else {
                    gl.clickButton(maeGUIObjects.SHARES_SUBMIT_BUTTON.get(0));
                }

                gl.waitProgress();
                gl.waitForProfileLoad();

                logInfo.pass("Assign shipment number to flight and click Submit");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            } catch (AssertionError | Exception e) {

                ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
                Assert.fail("This step failed.. so stopping...");
            }

        }
        clickSharesCancel(logInfo);

    }

