    public void selectAllFlightsOnSameDay(String cabin, ExtentTest logInfo) {
        int segmentsToCheck = 2;

        for (int i = 2; i < maeGUIObjects.FLIGHTS_AVAILABLE.size(); i = i + 2) {
            maeGUIObjects.FLIGHTS_AVAILABLE.get(i).click();
            if ((mPassengers.get(getDriverID()).get(0).getSecondSegDate()) == 0) {
                WebElement dateTimeDiv = driver.get().findElement(By.xpath("//div[contains(@class, 'date-time')]"));
                String fullText = dateTimeDiv.getText();
                String date = fullText.split("\\s+")[0];
                System.out.println("Extracted Date: " + date);
                String todayXpath = String.format("//div[@class='ng-binding' and text()='%s']", date.trim());
                WebElement TodayDate = driver.get().findElement(By.xpath(todayXpath));
                gl.clickElement(TodayDate);
            }
            gl.waitProgress();
            gl.waitForProfileLoad();
            if (cabin.equalsIgnoreCase("Economy")) {
                returnFullEconomy(logInfo, segmentsToCheck);

                returnEconomyOnSameday(logInfo, segmentsToCheck);
            } else if (cabin.equalsIgnoreCase("Business")) {
                returnBusinessOnSameDay(logInfo, segmentsToCheck);
            }
            segmentsToCheck++;
        }
    }
