                            String xpath_RFISC = String.format("//td[@class='ng-binding' and normalize-space(text())='%s']", rfiscNumber);
                            WebElement RFISC = driver.get().findElement(By.xpath(xpath_RFISC));
                            js.executeScript("arguments[0].style.border='3px solid red'", RFISC);
                            gl.waitProgress();
                            gl.waitForProfileLoad();
                            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                            logInfo.info(MarkupHelper.createLabel("Residual EMD and RFISC Value is available", ExtentColor.GREEN));
                            System.out.println("EMD element is visible and RFISC");

                            List<WebElement> CLOSINGARROW =driver.get().findElements(By.xpath("//div[contains(@class, 'toggle-heading') and .//div[contains(@class, 'togglediv-title') and contains(., 'D - FinancialImpact')]]//i[contains(@class, 'toggle-arrow') and contains(@class, 'icon-arrow-down')]"));
                            if(gl.existElement(CLOSINGARROW)) {
                                WebElement CLOSINGARROW1 =driver.get().findElement(By.xpath("//div[contains(@class, 'toggle-heading') and .//div[contains(@class, 'togglediv-title') and contains(., 'D - FinancialImpact')]]//i[contains(@class, 'toggle-arrow') and contains(@class, 'icon-arrow-down')]"));
                                gl.clickElement(CLOSINGARROW1);
                                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                            }
