    public void enterEmailIfRequired(ExtentTest logInfo)
    {
        try {
            List<WebElement> NEXTBUTTON = driver.get().findElements(By.xpath("//button[contains(@ng-click, 'foid') and normalize-space(text())='Next']"));
            List<WebElement> EMAILELEMENT = driver.get().findElements(By.xpath("//input[@ng-model='recipient.ToAddr']"));
            if (gl.existElement(NEXTBUTTON) || gl.existElement(EMAILELEMENT)) {
                if (gl.existElement(NEXTBUTTON)) {
                    gl.scrollToWebElement(maeGUIObjects.FOID_NEXT_BUTTON);
                    gl.clickButton(maeGUIObjects.FOID_NEXT_BUTTON);
                    gl.waitProgress();
                    gl.waitForProfileLoad();
                }

                String email = maeGUIObjects.INPUT_RECIPIENT_EMAIL.getAttribute("value");

                if (StringUtils.isEmpty(email) || !email.equalsIgnoreCase("testone@testone.com")) {
                    email = "testone@testone.com";

                    maeGUIObjects.INPUT_RECIPIENT_EMAIL.clear();
                    maeGUIObjects.INPUT_RECIPIENT_EMAIL.sendKeys(email);
                    gl.waitForProfileLoad();
                }

                maeGUIObjects.EmailRecipient_dropDown.click();
                gl.waitForProfileLoad();
                maeGUIObjects.EmailLanguageSelect.click();
                gl.waitForProfileLoad();
                logInfo.pass("I enter the details in the email recipients page");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                maeGUIObjects.EmailButton.click();
                gl.waitProgress();
                WebDriverWait wait = new WebDriverWait(getDriver(), Duration.ofSeconds(120));
                wait.until(ExpectedConditions.invisibilityOfElementLocated(By.xpath("//div[@ng-repeat='(key, val) in spinnerMessage.pssguiSpinnerMessageUtil.loadingMessage']")));
                if (gl.existElement(maeGUIObjects.EMAIL_MESSAGE_LOGS)) {
                    gl.clickElement(maeGUIObjects.EMAIL_MESSAGE_LOGS_DROPDOWN);
                    gl.waitProgress();
                    logInfo.pass("I click on the message logs");
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    if (gl.existElement(maeGUIObjects.EMAIL_ALL_MESSAGES) && maeGUIObjects.EMAIL_ALL_MESSAGES.size() > 1) {
                        for (WebElement message : maeGUIObjects.EMAIL_ALL_MESSAGES) {
                            JavascriptExecutor js = (JavascriptExecutor) getDriver();
                            String Message = message.getText().trim();
                            if (Message.contains("Value cannot be null.")) {
                                js.executeScript("arguments[0].style.border='3px solid red'", message);
                                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                            }
                            if (Message.contains("The purchase operation failed")) {
                                js.executeScript("arguments[0].style.border='3px solid red'", message);
                                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                            }
                        }
                        Assert.fail("Test case failing due to errors");
                    }
                }
                String expected = "Payment Successful";
                String actual = maeGUIObjects.PAYMENT_SUCCESSFUL.getText();
                Assert.assertEquals(expected, actual);

                logInfo.pass("Validated the message - Payment Successful");
                waitUntilPageLoad(logInfo);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                maeGUIObjects.PaymentDoneButton.click();
                gl.waitProgress();
                gl.waitForProfileLoad();
            }
        }
        catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

    public void selectFullEconomyForSameDayBooking(ExtentTest logInfo) {
        int pcount, maxSeats = 2, businessMax = 0;
        Passenger pax=mPassengers.get(getDriverID()).get(0);
        int a=pax.getFirstSegDate();
        int segmentCount = maeGUIObjects.SEGMENT_FLIGHTS.size();
        boolean flightNotFound = gl.existElement(maeGUIObjects.FLIGHT_NOT_FOUND);
        boolean noMatchingFlightFound =gl.existElement(maeGUIObjects.NO_MATCHING_FLIGHT_FOUND);

        if (segmentCount == 0 || (flightNotFound&&noMatchingFlightFound)) {
            getCaroselDateCounts(logInfo,a);
        }

        if(maeGUIObjects.CAROUSEL_NEXT_DATES.size()==0){
            maeGUIObjects.CAROUSEL_RIGHT_ARROW.click();
            gl.waitProgress();
        }

        if (mCheckBusinessClass.get(getDriverID()).equalsIgnoreCase("true")) {
            try {
                Dates:
                for (WebElement NextDt : maeGUIObjects.CAROUSEL_NEXT_DATES) {

                    FlightSegment:
                    for (WebElement segment : maeGUIObjects.SEGMENT_FLIGHTS) {
                        WebElement flightNo = segment.findElement(By.xpath(".//div[@class='ng-binding']"));
                        List<WebElement> Code_Share = segment.findElements(By.xpath(".//div[@translate='pssgui.codeshare.flight']"));

                        if (flightNo.getText().length() >= 4 && (flightNo.getText().contains("CM") || flightNo.getText().contains("UA")) && (Code_Share.size() != 1)) {
                            List<WebElement> seats = segment.findElements(By.xpath(".//span[contains(@class, 'small-box')]"));

                            for (WebElement seat : seats) {
                                String label = seat.getText();
                                pcount = label.length() == 2 ? Integer.parseInt(String.valueOf(label.charAt(1))) : Integer.parseInt(String.valueOf(label.charAt(2)));

                                if (label.contains("C")) {
                                    if (pcount > businessMax)
                                        businessMax = pcount;
                                }

                                if ((label.contains("Y") || label.contains("B") || label.contains("M") || label.contains("H") || label.contains("Q")
                                        || label.contains("K") || label.contains("V") || label.contains("U") || label.contains("S") || label.contains("O") ||
                                        label.contains("W") || label.contains("E") || label.contains("L") || label.contains("T") || label.contains("A")) && (businessMax >= maxSeats)) {

                                    if (pcount >= mPassengers.get(getDriverID()).size()) {

                                        gl.scrollToWebElement(seat);
                                        seat.click();
                                        String date= "";
                                        if (gl.existElement(maeGUIObjects.FIRST_SEGMENT_DATE_ORDER_PAGE_1)) {
                                            date = maeGUIObjects.FIRST_SEGMENT_DATE_ORDER_PAGE.getText().trim();
                                            pax.setfirstSegDateOrderPage(date);
                                            break;
                                        }
                                        else if (maeGUIObjects.REMOVE_ICONS_AVAILABLE.size() < 1){
                                            logInfo.info(MarkupHelper.createLabel("Seats are not selected or only codeshare/connecting flights are available, hence unable to book the flight for same day", ExtentColor.RED));

                                            Assert.fail("Seats are not selected or only codeshare/connecting flights are available, hence unable to book the flight for same day");
                                        }
                                    }
                                }
                            }
                            if (maeGUIObjects.REMOVE_ICONS_AVAILABLE.size() >= 1) {
                                break Dates;
                            }
                        }
                    }
                    maeGUIObjects.CAROUSEL_RIGHT_ARROW.click();
                    NextDt.click();
                    gl.waitProgress();
                }
            } catch (AssertionError | Exception e) {

                ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
                Assert.fail("This step failed.. so stopping...");
            }

        } else {
            try {

                Dates:
                for (WebElement NextDt : maeGUIObjects.CAROUSEL_NEXT_DATES) {

                    FlightSegment:
                    for (WebElement segment : maeGUIObjects.SEGMENT_FLIGHTS) {
                        WebElement flightNo = segment.findElement(By.xpath(".//div[@class='ng-binding']"));
                        List<WebElement> Code_Share = segment.findElements(By.xpath(".//div[@translate='pssgui.codeshare.flight']"));

                        if (flightNo.getText().length() >= 4 && (flightNo.getText().contains("CM") || flightNo.getText().contains("UA")) && (Code_Share.size() != 1)) {
                            List<WebElement> seats = segment.findElements(By.xpath(".//span[contains(@class, 'small-box')]"));

                            for (WebElement seat : seats) {
                                String label = seat.getText();
                                pcount = label.length() == 2 ? Integer.parseInt(String.valueOf(label.charAt(1))) : Integer.parseInt(String.valueOf(label.charAt(2)));

                                if ((label.contains("Y") || label.contains("B") || label.contains("M") || label.contains("H") || label.contains("Q")
                                        || label.contains("K") || label.contains("V") || label.contains("U") || label.contains("S") || label.contains("O") ||
                                        label.contains("W") || label.contains("E") || label.contains("L") || label.contains("T") || label.contains("A")) && (pcount >= maxSeats)) {

                                    if (pcount >= mPassengers.get(getDriverID()).size()) {

                                        gl.scrollToWebElement(seat);
                                        seat.click();
                                        String date= "";
                                        if (gl.existElement(maeGUIObjects.FIRST_SEGMENT_DATE_ORDER_PAGE_1)) {
                                            date = maeGUIObjects.FIRST_SEGMENT_DATE_ORDER_PAGE.getText().trim();
                                            pax.setfirstSegDateOrderPage(date);
                                            break;
                                        } else if (maeGUIObjects.REMOVE_ICONS_AVAILABLE.size() < 1){
                                            logInfo.info(MarkupHelper.createLabel("Seats are not selected or only codeshare/connecting flights are available, hence unable to book the flight for same day", ExtentColor.RED));

                                            Assert.fail("Seats are not selected or only codeshare/connecting flights are available, hence unable to book the flight for same day");
                                        }
                                    }
                                }
                            }
                            if (maeGUIObjects.REMOVE_ICONS_AVAILABLE.size() >= 1) {
                                break Dates;
                            }

                        }

                    }
                    maeGUIObjects.CAROUSEL_RIGHT_ARROW.click();
                    NextDt.click();
                    gl.waitProgress();
                }
            } catch (AssertionError | Exception e) {

                ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
                Assert.fail("This step failed.. so stopping...");
            }
        }


    }

    public void selectFullBusinessForSameDayBooking(ExtentTest logInfo) {
        int pcount;
        Passenger pax=mPassengers.get(getDriverID()).get(0);
        int a=pax.getFirstSegDate();
        int segmentCount = maeGUIObjects.SEGMENT_FLIGHTS.size();
        boolean flightNotFound = gl.existElement(maeGUIObjects.FLIGHT_NOT_FOUND);
        boolean noMatchingFlightFound =gl.existElement(maeGUIObjects.NO_MATCHING_FLIGHT_FOUND);

        if (segmentCount == 0 || (flightNotFound&&noMatchingFlightFound)) {
            getCaroselDateCounts(logInfo,a);
        }

        if(maeGUIObjects.CAROUSEL_NEXT_DATES.size()==0){
            maeGUIObjects.CAROUSEL_RIGHT_ARROW.click();
            gl.waitProgress();
        }
        try {
            Dates:
            for (WebElement NextDt : maeGUIObjects.CAROUSEL_NEXT_DATES) {

                gl.waitForProfileLoad();
                FlightSegment:
                for (WebElement segment : maeGUIObjects.SEGMENT_FLIGHTS) {
                    WebElement flightNo = segment.findElement(By.xpath(".//div[@class='ng-binding']"));
                    List<WebElement> Code_Share = segment.findElements(By.xpath(".//div[@translate='pssgui.codeshare.flight']"));

                    if ((flightNo.getText().length() >= 4) && (flightNo.getText().contains("CM") || flightNo.getText().contains("UA")) && (!segment.getText().contains("Codeshare Flight"))) {
                        List<WebElement> seats = segment.findElements(By.xpath(".//span[contains(@class, 'small-box')]"));

                        for (WebElement seat : seats) {
                            String label = seat.getText();
                            pcount = label.length() == 2 ? Integer.parseInt(String.valueOf(label.charAt(1))) : Integer.parseInt(String.valueOf(label.charAt(2)));

                            if ((label.contains("C") || label.contains("J") || label.contains("D") || label.contains("R")) && pcount >= 5) {

                                if (pcount >= mPassengers.get(getDriverID()).size()) {
                                    gl.scrollToWebElement(seat);
                                    seat.click();
                                    String date= "";
                                    if (gl.existElement(maeGUIObjects.FIRST_SEGMENT_DATE_ORDER_PAGE_1)) {
                                        date = maeGUIObjects.FIRST_SEGMENT_DATE_ORDER_PAGE.getText().trim();
                                        pax.setfirstSegDateOrderPage(date);
                                        break;
                                    } else if (maeGUIObjects.REMOVE_ICONS_AVAILABLE.size() < 1){
                                        logInfo.info(MarkupHelper.createLabel("Seats are not selected or only codeshare/connecting flights are available, hence unable to book the flight for same day", ExtentColor.RED));

                                        Assert.fail("Seats are not selected or only codeshare/connecting flights are available, hence unable to book the flight for same day");
                                    }


                                }
                            }
                        }
                        if (maeGUIObjects.REMOVE_ICONS_AVAILABLE.size() >= 1) {
                            break Dates;
                        }

                    }
                }
                maeGUIObjects.CAROUSEL_RIGHT_ARROW.click();
                NextDt.click();
            }
        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

